web/card-studio-shell.css:
/* Suite Card Studio. Scoped to this document and its own root, never card content or mask coordinates. */
html[data-atelier-card-studio="true"],html[data-atelier-card-studio="true"] body{margin:0;height:100%;overflow:hidden;}
#workshop[data-integrated="true"]{--page-pad:clamp(20px,3vw,46px);font-family:"Segoe UI",system-ui,sans-serif;}
#workshop[data-integrated="true"] .app-shell{grid-template-columns:230px minmax(0,1fr);}
#workshop[data-integrated="true"] .topbar{height:auto;min-height:0;display:grid;grid-template-columns:minmax(120px,1fr) auto;grid-template-areas:"crumb suite" "search search";gap:10px 20px;padding:16px var(--page-pad);flex:0 0 auto;background:var(--sidebar);}
#workshop[data-integrated="true"] .breadcrumb{grid-area:crumb;min-width:0;flex-wrap:wrap;row-gap:4px;font-size:13px;}
#workshop[data-integrated="true"] .breadcrumb strong{max-width:min(35vw,420px);}
#workshop[data-integrated="true"] .suite-header-actions{grid-area:suite;display:flex;align-items:center;gap:8px;flex-wrap:wrap;justify-content:flex-end;}
#workshop[data-integrated="true"] .suite-world{display:flex;align-items:center;gap:8px;margin:0;font-size:11px;color:var(--muted);}
#workshop[data-integrated="true"] .suite-world select{width:150px;min-height:38px;color:var(--fg);background:var(--panel);border:1px solid var(--line);border-radius:10px;font:13px "Segoe UI",system-ui,sans-serif;padding:8px;}
#workshop[data-integrated="true"] .suite-world[hidden]{display:none;}
#workshop[data-integrated="true"] .top-actions{grid-area:search;display:flex;flex-wrap:nowrap;min-width:0;}
#workshop[data-integrated="true"] .command-trigger{width:auto;flex:1;min-width:0;max-width:640px;min-height:38px;background:var(--panel);}
#workshop[data-integrated="true"] .top-actions .icon-btn{flex:0 0 36px;}
#workshop[data-integrated="true"] .sidebar{padding:28px 15px 18px;gap:25px;}
#workshop[data-integrated="true"] .brand strong{font:750 29px/1 "Segoe UI",system-ui,sans-serif;letter-spacing:-1.5px;}
#workshop[data-integrated="true"] .brand small{font:600 9px/1.4 "Segoe UI",system-ui,sans-serif;letter-spacing:1.6px;}
#workshop[data-integrated="true"] .nav-link{min-height:42px;font-size:13px;border-radius:12px;}
#workshop[data-integrated="true"] .page{max-width:1550px;padding-block:30px 40px;}
#workshop[data-suite-theme="true"] .page-heading h1,#workshop[data-suite-theme="true"] .project-hero h1{font-family:var(--world-heading,Georgia,serif);font-size:clamp(30px,3.5vw,46px);line-height:1.15;letter-spacing:-1px;}
#workshop[data-suite-theme="true"] .page-heading p{font-size:14px;line-height:1.65;max-width:700px;}
#workshop[data-suite-theme="true"] .summary-strip{background:linear-gradient(130deg,var(--panel),var(--raised));border-radius:var(--world-radius,18px);padding-block:18px;}
#workshop[data-integrated="true"] .summary-number strong{font:650 29px/1.3 "Segoe UI",system-ui,sans-serif;font-variant-numeric:tabular-nums;}
#workshop[data-suite-theme="true"] .studio-panel,#workshop[data-suite-theme="true"] .panel,#workshop[data-suite-theme="true"] .library-note,#workshop[data-suite-theme="true"] .settings-section{border-radius:var(--world-radius,18px);border-color:var(--line);}
#workshop[data-integrated="true"] button{font-family:"Segoe UI",system-ui,sans-serif;}
#workshop[data-integrated="true"] button:hover{transform:none;}
#workshop[data-integrated="true"] button:focus-visible,#workshop[data-integrated="true"] input:focus-visible,#workshop[data-integrated="true"] select:focus-visible,#workshop[data-integrated="true"] textarea:focus-visible{outline:2px solid var(--accent);outline-offset:3px;}
#workshop[data-integrated="true"] .shared-world-note{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:18px;line-height:1.7;margin:16px 0;}
#workshop[data-integrated="true"] .shared-world-note strong{color:var(--fg);}
#workshop[data-integrated="true"] .shared-world-note p{font-size:13px;margin:7px 0 0;color:var(--muted);}
#workshop[data-integrated="true"] .source-text{font-size:14px;line-height:1.75;}
#workshop[data-integrated="true"] input,#workshop[data-integrated="true"] textarea,#workshop[data-integrated="true"] select{color-scheme:inherit;}
#workshop[data-integrated="true"] .page-scroll{scroll-behavior:auto;scrollbar-color:var(--line) var(--bg);}
#workshop[data-integrated="true"] #ws-dialog{color-scheme:inherit;}
#workshop[data-integrated="true"] .dialog-body{min-height:0;overscroll-behavior:contain;}
#workshop[data-integrated="true"] .dialog-head,#workshop[data-integrated="true"] .dialog-foot{flex-shrink:0;}
@media(max-width:1050px){
 #workshop[data-integrated="true"] .app-shell{grid-template-columns:190px minmax(0,1fr);}
 #workshop[data-integrated="true"] .topbar{grid-template-areas:"crumb crumb" "suite suite" "search search";gap:8px;}
 #workshop[data-integrated="true"] .suite-header-actions{justify-content:flex-start;}
 #workshop[data-integrated="true"] .breadcrumb strong{max-width:70vw;}
}
@media(max-width:700px){
 #workshop[data-integrated="true"] .app-shell{grid-template-columns:64px minmax(0,1fr);}
 #workshop[data-integrated="true"] .sidebar{padding:16px 8px;gap:20px;}
 #workshop[data-integrated="true"] .brand{padding:0;justify-content:center;}
 #workshop[data-integrated="true"] .brand>div,#workshop[data-integrated="true"] .brand small,#workshop[data-integrated="true"] .nav-title,#workshop[data-integrated="true"] .recent-section,#workshop[data-integrated="true"] .side-footer{display:none;}
 #workshop[data-integrated="true"] .nav-link{padding:10px;justify-content:center;min-height:42px;position:relative;}
 #workshop[data-integrated="true"] .nav-count{position:absolute;right:0;top:0;}
 #workshop[data-integrated="true"] .summary-strip{grid-template-columns:1fr 1fr;gap:15px 0;}
 #workshop[data-integrated="true"] .summary-number{padding:0 15px;}
 #workshop[data-integrated="true"] .summary-number:nth-child(2){border-right:0;}
 #workshop[data-integrated="true"] .page-heading{align-items:flex-start;flex-wrap:wrap;gap:15px;}
 #workshop[data-integrated="true"] .command-trigger kbd{display:none;}
 #workshop[data-integrated="true"] .suite-world{flex:1;min-width:0;}
 #workshop[data-integrated="true"] .suite-world select{width:100%;min-width:0;}
 #workshop[data-integrated="true"] .suite-header-actions>.quiet{font-size:12px;padding:8px;min-height:38px;}
}
@media(max-width:440px){
 #workshop[data-integrated="true"]{--page-pad:14px;}
 #workshop[data-integrated="true"] .suite-world{flex-basis:100%;}
 #workshop[data-integrated="true"] .command-trigger span{font-size:11px;}
 #workshop[data-integrated="true"] .top-actions{gap:4px;}
 #workshop[data-integrated="true"] .page-heading h1{font-size:29px;}
 #workshop[data-integrated="true"] .form-grid{grid-template-columns:1fr;}
}
@media(prefers-reduced-motion:reduce){#workshop[data-integrated="true"] *,#workshop[data-integrated="true"] *::before,#workshop[data-integrated="true"] *::after{animation:none!important;transition:none!important;scroll-behavior:auto!important;}}
#workshop[data-motion="off"] *,#workshop[data-motion="off"] *::before,#workshop[data-motion="off"] *::after{transition:none!important;animation:none!important;}

/* Error feedback belongs inside the native modal top layer, never behind masks. */
html[data-atelier-card-studio] #workshop .ws-modal-alerts{display:grid;gap:8px;max-height:180px;overflow:auto;margin:0 0 14px;}
html[data-atelier-card-studio] #workshop .ws-modal-alerts .toast{position:static;max-width:100%;min-width:0;overflow-wrap:anywhere;box-shadow:none;}
html[data-atelier-card-studio] #workshop .ws-modal-alerts .toast>span{min-width:0;}
html[data-atelier-card-studio] #workshop .modal-heading,html[data-atelier-card-studio] #workshop .modal-footer{flex:0 0 auto;}

/* rc3 discoverability: one source store, visible unfinished work and explicit approval. */
#workshop[data-integrated="true"] .main-nav{flex:0 0 auto;gap:3px;}
#workshop[data-integrated="true"] .sidebar{overflow-y:auto;overscroll-behavior:contain;gap:18px;}
#workshop[data-integrated="true"] .nav-link{font-size:12px;min-height:39px;line-height:1.4;}
#workshop[data-integrated="true"] .ws-authoring-workflow{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:14px 16px;margin:0 0 18px;background:var(--raised);border:1px solid var(--line);border-radius:14px;}
#workshop[data-integrated="true"] .ws-authoring-workflow>div:first-child{flex:1;min-width:180px;}
#workshop[data-integrated="true"] .ws-authoring-workflow strong{font:600 13px/1.5 "Segoe UI",system-ui,sans-serif;}
#workshop[data-integrated="true"] .ws-authoring-workflow small{display:block;font-size:12px;line-height:1.55;color:var(--muted);margin-top:3px;max-width:540px;}
#workshop[data-integrated="true"] .ws-authoring-workflow .row{flex:0 1 auto;}
#workshop[data-integrated="true"] .ws-draft-filters{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(0,1fr);gap:16px;margin:0 0 18px;}
#workshop[data-integrated="true"] .ws-draft-batch{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:12px;margin-bottom:16px;font-size:13px;color:var(--muted);}
#workshop[data-integrated="true"] .ws-draft-results{display:grid;gap:12px;}
#workshop[data-integrated="true"] .ws-inbox-record{border:1px solid var(--line);border-radius:16px;padding:15px 18px;background:var(--panel);min-width:0;}
#workshop[data-integrated="true"] .ws-draft-meta{display:flex;flex-wrap:wrap;justify-content:space-between;gap:6px 16px;color:var(--muted);font-size:11px;line-height:1.5;padding-bottom:10px;border-bottom:1px solid var(--line);}
#workshop[data-integrated="true"] .ws-draft-meta>span{overflow-wrap:anywhere;min-width:0;}
#workshop[data-integrated="true"] .ws-inbox-record .draft-item{border:0;margin:10px 0 0;padding:0;background:none;}
#workshop[data-integrated="true"] .ws-inbox-record .draft-copy h3{font:600 15px/1.55 "Segoe UI",system-ui,sans-serif;overflow-wrap:anywhere;}
#workshop[data-integrated="true"] .ws-inbox-record .draft-copy p{font-size:13px;line-height:1.6;}
#workshop[data-integrated="true"] .ws-draft-pagination{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:20px 0;font-size:12px;color:var(--muted);}
#workshop[data-integrated="true"] .ws-import-card{max-width:1000px;padding:clamp(20px,3vw,36px);}
#workshop[data-integrated="true"] .ws-import-choices{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:25px 0;}
#workshop[data-integrated="true"] .ws-import-choice{display:flex;flex-direction:column;align-items:flex-start;gap:10px;padding:22px 18px;border:1px solid var(--line);border-radius:14px;background:var(--bg);text-align:left;white-space:normal;}
#workshop[data-integrated="true"] .ws-import-choice svg{color:var(--accent);}
#workshop[data-integrated="true"] .ws-import-choice strong{font-size:15px;line-height:1.4;}
#workshop[data-integrated="true"] .ws-import-choice small{font-size:12px;line-height:1.65;color:var(--muted);}
#workshop[data-integrated="true"] .ws-import-choice:hover{background:var(--raised);border-color:var(--accent);}
#workshop[data-integrated="true"] .ws-import-note{margin:24px 0 0;border-top:1px solid var(--line);padding-top:18px;}
@media(max-width:1100px){#workshop[data-integrated="true"] .ws-authoring-workflow{flex-wrap:wrap;}}
@media(max-width:760px){#workshop[data-integrated="true"] .ws-draft-filters,#workshop[data-integrated="true"] .ws-import-choices{grid-template-columns:1fr;}#workshop[data-integrated="true"] .ws-import-choice{gap:7px;padding:18px;}#workshop[data-integrated="true"] .ws-draft-meta{flex-direction:column;}#workshop[data-integrated="true"] .ws-authoring-workflow>div:first-child{min-width:0;}}

.figure-tile img[data-figure-index]:not([src]){display:block;width:100%;min-height:110px;background:var(--ws-panel,var(--panel,#283128));border-radius:10px;}
.figure-loading{display:block;padding:10px;font:12px/1.5 system-ui;color:inherit;opacity:.8}.figure-loading[hidden]{display:none}

#workshop #ws-destination-results{display:grid;gap:8px;margin-top:16px;max-height:48vh;overflow:auto;padding:3px}
#workshop .ws-destination{display:grid;grid-template-columns:minmax(0,1fr) auto;width:100%;text-align:left;gap:7px;padding:14px;border:1px solid var(--line);border-radius:12px;background:var(--panel);color:var(--text);font-size:14px}
#workshop .ws-destination span{min-width:0;overflow-wrap:anywhere}#workshop .ws-destination small{color:var(--muted);font-size:12px}#workshop .ws-destination:hover{border-color:var(--accent)}

web/home-shell.css:
/* rc4: task-first Home / Library / Tools. Scoped to Atelier's ShadowRoot.
   No card, native-home, engine or reviewer selectors. */
.layout .unified-topbar{position:sticky;top:0;z-index:30;display:grid;grid-template-columns:minmax(118px,1fr) minmax(0,auto);gap:12px;align-items:center;padding:14px 28px;min-height:78px;height:auto;background:var(--bg);border-bottom:1px solid var(--line-soft);box-shadow:none;}
.unified-topbar .topbar-left{min-width:0;display:flex;flex:initial;padding:0;align-self:center;}
.unified-topbar .owner-badge{font-size:12px;letter-spacing:0;line-height:1.4;text-transform:none;white-space:normal;text-align:left;}
.unified-topbar .top-actions{display:flex;flex-wrap:nowrap;min-width:0;gap:8px;align-items:center;}
.unified-topbar .search{display:flex;min-width:130px;width:clamp(140px,19vw,300px);max-width:300px;height:40px;}
.unified-topbar .search input{min-width:0;width:100%;font-size:13px;}
.unified-topbar :is(.add-cards-top,.browse-top,.sync-top){height:40px;min-height:40px;font-size:13px;padding:9px 13px;white-space:nowrap;}
.unified-topbar :is(.refresh-library,[data-action="appearance"]){height:38px;width:38px;flex:0 0 38px;}
.unified-topbar .sample-label{font-size:9px;letter-spacing:.4px;white-space:normal;}
.main-inner{padding:22px 28px 30px;max-width:1490px;}
.sidebar .nav-group{gap:2px;padding-bottom:14px;}
.sidebar .nav-row{min-height:38px;padding:8px 11px;font-size:13px;}
.sidebar .side-label{font-size:10px;letter-spacing:1.05px;}
.sidebar .tree-row{min-height:42px;padding-block:3px;max-height:none;transform:none;}
.sidebar .tree-name{line-height:1.45;font-size:12px;overflow-wrap:normal;word-break:normal;}
.sidebar .tree-open{min-width:0;min-height:34px;}
.sidebar .tree-open small{margin-left:auto;}
.sidebar .tree-art{width:25px;flex:0 0 25px;}
.sidebar .side-scroll{overflow-x:hidden;}
.layout[data-page="library"] .side-utility-links{padding-bottom:6px;}
.layout[data-page="library"] .recent-label,.layout[data-page="library"] .recent-links{display:none;}
/* Compact composition: usable lectures come before lower-priority modules. */
.task-focus.focus-panel.quiet-focus{grid-template-columns:minmax(0,1fr) minmax(210px,27%);}
.task-focus.quiet-focus .focus-intro{padding:25px 27px 24px;min-width:0;}
.task-focus.quiet-focus h1{font-size:clamp(25px,2.55vw,37px);line-height:1.13;max-width:26ch;font-weight:500;letter-spacing:-.85px;}
.task-focus.quiet-focus .eyebrow{font-size:10px;letter-spacing:1.35px;margin-bottom:13px;}
.task-focus.quiet-focus .focus-intro>p{margin-top:12px;max-width:60ch;font-size:13px;line-height:1.6;}
.task-focus .focus-actions{margin-top:18px;gap:9px;align-items:center;}
.task-focus .focus-actions :is(.primary,.secondary,.quiet){min-height:39px;font-size:12px;}
.task-focus.quiet-focus .focus-agenda{display:flex;flex-direction:column;justify-content:center;gap:11px;padding:21px 22px 20px 0;min-width:0;}
.task-focus .world-window{width:100%;height:174px;min-height:174px;border-radius:calc(var(--world-radius,20px) * .75);margin:0;}
.task-focus .world-window-label{padding:13px 15px;}
.task-focus .world-window-label strong{font-size:20px;line-height:1.15;}
.task-focus .focus-quiet-note{font-size:10px;line-height:1.55;color:var(--muted);display:flex;gap:7px;align-items:center;}
.task-focus .focus-footer{padding:12px 26px!important;gap:18px;}
.task-focus .focus-metric{padding-right:18px;gap:8px;}
.task-focus .focus-metric strong{font-size:23px;letter-spacing:-.6px;}
.task-focus .focus-metric span,.task-focus .scope-note{font-size:10px;}
.resume-lecture{display:flex;align-items:center;gap:11px;padding:12px 13px;background:var(--panel);border:1px solid var(--line-soft);border-radius:11px;margin-top:17px;max-width:650px;}
.resume-glyph{flex:0 0 25px;color:var(--tone);}
.resume-lecture>div{flex:1;min-width:0;}
.resume-lecture strong{display:block;font-size:14px;font-weight:600;line-height:1.45;overflow-wrap:anywhere;}
.resume-lecture small{display:block;font-size:10px;line-height:1.5;color:var(--muted);max-width:100%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:3px;}
.resume-available{font-size:10px;color:var(--muted);white-space:nowrap;}
.desk-revisit{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin-top:26px;}
.revisit-column{min-width:0;border:1px solid var(--line);background:var(--panel);border-radius:16px;padding:15px 18px;}
.revisit-column>header{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:10px;}
.revisit-column h2{font-size:15px;letter-spacing:-.25px;}
.revisit-column>header .quiet{font-size:11px;padding:5px;min-height:28px;}
.revisit-row{display:flex;gap:8px;align-items:center;border-top:1px solid var(--line-soft);padding:9px 0;}
.revisit-row>button:first-child{display:flex;gap:10px;align-items:center;flex:1;min-width:0;text-align:left;padding:3px;}
.revisit-row>button:first-child>span:last-child{min-width:0;flex:1;}
.revisit-row strong{display:block;font-size:12px;line-height:1.5;font-weight:600;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;}
.revisit-row small{display:block;font-size:10px;line-height:1.55;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.revisit-row>button:hover strong{color:var(--accent-strong);}
.revisit-glyph{color:var(--tone);flex:0 0 20px;}
.revisit-empty{padding:14px 0 11px;color:var(--muted);font-size:12px;line-height:1.75;}
.desk-tools{margin-top:24px;}
.suite-exams{margin-top:28px;}
/* Library: navigation, collection edits and review actions have separate roles. */
.library{scroll-margin-top:106px;}
.library-orientation{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:0 0 16px;padding:10px 13px;border:1px solid var(--line-soft);background:var(--side);border-radius:10px;}
.library-orientation>span{display:flex;align-items:center;gap:8px;font-size:11px;color:var(--muted);line-height:1.55;min-width:0;}
.library-orientation .quiet{font-size:11px;padding:4px 8px;min-height:28px;flex-shrink:0;}
.library .section-heading{align-items:flex-start;gap:17px;margin-bottom:16px;}
.library .section-heading h2{font-size:23px;font-weight:600;letter-spacing:-.55px;line-height:1.3;}
.library .section-heading p{font-size:12px;line-height:1.65;max-width:62ch;}
.library .library-actions{max-width:54%;gap:6px;}
.library-controls{gap:12px;}
.library-controls .view-tools{min-width:0;gap:10px;}
.library-controls select{min-width:0;max-width:100%;font-size:12px;}
.location-bar{margin-bottom:12px;}
.breadcrumbs{flex-wrap:wrap;row-gap:3px;min-width:0;}
.breadcrumbs .crumb{font-size:11px;max-width:250px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-height:30px;}
.cards:not(.list){grid-template-columns:repeat(auto-fill,minmax(min(100%,254px),1fr));gap:16px;}
.cards:not(.list) .deck-card{min-width:0;padding:19px 18px 0;}
.cards:not(.list) .card-head{margin-bottom:11px;}
.cards:not(.list) .card-art{width:44px;height:40px;}
.cards:not(.list) .card-art svg{width:44px;height:40px;}
.cards:not(.list) .card-title{font-size:16px;line-height:1.45;font-weight:600;}
.cards:not(.list) .card-description{font-size:11px;line-height:1.55;margin-top:6px;}
.cards:not(.list) .card-type{font-size:9px;letter-spacing:1px;}
.cards:not(.list) .card-bottom{margin-inline:-18px;}
.cards:not(.list) .card-peek{font-size:11px;border:1px solid var(--line-soft);margin-top:12px;padding:8px;}
.card-shortcuts .peek-row{display:flex;min-width:0;align-items:center;}
.card-shortcuts .peek-row>button:first-child{flex:1;min-width:0;}
.card-shortcuts .peek-row>button:first-child>span{white-space:normal;overflow-wrap:anywhere;line-height:1.5;}
/* Reset the old card-as-list positioning. The same IDs/actions/ordering survive. */
.cards.list{display:flex;flex-direction:column;gap:8px;}
.cards.list .library-row{display:block;min-height:0;padding:0;overflow:hidden;border:1px solid var(--line);border-radius:12px;background:var(--panel);box-shadow:none;transform:none;}
.library-row-main{display:grid;grid-template-columns:minmax(150px,1fr) minmax(125px,180px) auto;gap:14px;align-items:center;padding:13px 15px;min-width:0;}
.library-row-name{display:flex;align-items:center;min-width:0;gap:8px;}
.library-row-name>div{min-width:0;flex:1;}
.cards.list .library-row .card-title{display:block;grid-area:auto;font-size:14px;line-height:1.5;letter-spacing:0;text-align:left;white-space:normal;overflow-wrap:anywhere;}
.cards.list .library-row .card-path{grid-area:auto;max-width:100%;font-size:10px;margin-top:5px;}
.list-preview-toggle,.list-preview-spacer{width:26px;height:30px;flex:0 0 26px;}
.list-glyph{width:29px;flex:0 0 29px;color:var(--tone);}
.list-glyph svg{width:29px;height:30px;}
.list-meta{display:flex;gap:8px;flex-wrap:wrap;margin-top:5px;color:var(--muted);font-size:10px;align-items:center;}
.list-meta>span+span{border-left:1px solid var(--line);padding-left:8px;}
.list-meta .focus-badge{color:var(--accent-strong);font-weight:600;}
.row-counts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;text-align:right;font-size:13px;font-variant-numeric:tabular-nums;}
.row-counts small{display:block;color:var(--muted);font-size:9px;margin-top:2px;}
.library-row-actions{display:flex;align-items:center;gap:3px;}
.library-row-actions .icon-button{width:31px;flex:0 0 31px;height:33px;}
.library-row-actions .row-open{font-size:11px;min-height:32px;padding:6px;}
.cards.list .library-row-preview{border-top:1px solid var(--line-soft);padding:11px 16px 13px 60px;background:var(--side);}
.cards.list .library-row-preview .card-shortcuts{display:flex;max-width:100%;margin:0;padding:0;border:0;grid-area:auto;background:transparent;}
.cards.list .library-row-preview .peek-row{max-width:none;}
/* Tools: grouped, searchable native routes. Notes do not imply new confirmations. */
.tools-heading{padding:4px 0 17px!important;}
.tools-heading .eyebrow{margin-bottom:11px;}
.tools-heading h1{font-family:var(--studio-font);font-size:clamp(29px,3.3vw,44px);letter-spacing:-.9px;line-height:1.15;}
.tools-heading p{font-size:13px;line-height:1.7;color:var(--muted);margin-top:12px;}
.tools-spotlight{padding:13px 15px;background:var(--panel);border:1px solid var(--line);border-radius:13px;display:flex;gap:9px;flex-wrap:wrap;margin-bottom:21px;}
.tools-spotlight :is(.secondary,.quiet){font-size:12px;min-height:37px;}
.tools-filter-bar{display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap;margin-bottom:24px;}
.tool-categories{display:flex;gap:5px;flex-wrap:wrap;}
.tool-category{padding:8px 11px;border:1px solid transparent;border-radius:8px;color:var(--muted);font-size:12px;min-height:34px;line-height:1.5;}
.tool-category.selected{color:var(--accent-strong);background:var(--accent-soft);border-color:var(--line);}
.tool-category:hover{background:var(--raised);color:var(--text);}
.tool-result-count{font-size:11px;color:var(--muted);}
.tools-group{margin-top:23px;}
.tools-group-heading{display:flex;align-items:baseline;gap:15px;flex-wrap:wrap;margin-bottom:12px;}
.tools-group-heading h2{font-size:17px;letter-spacing:-.3px;text-transform:none;}
.tools-group-heading p{font-size:11px;color:var(--muted);}
.tools-grid{grid-template-columns:repeat(auto-fill,minmax(min(100%,275px),1fr));gap:11px;}
.tool-entry{border:1px solid var(--line);background:var(--panel);border-radius:13px;min-width:0;overflow:hidden;}
.tool-entry:focus-within{border-color:var(--accent);}
.tools-grid .tool-tile{border:0;border-radius:0;box-shadow:none;padding:17px 15px;display:flex;align-items:flex-start;gap:12px;min-height:129px;width:100%;height:100%;background:transparent;transform:none;}
.tools-grid .tool-tile:hover{background:var(--raised);transform:none;}
.tool-tile>span:nth-child(2){min-width:0;flex:1;}
.tool-tile>svg:last-child{margin-top:3px;color:var(--quiet);}
.tool-symbol{width:33px;height:35px;flex:0 0 33px;border-radius:9px;background:var(--accent-soft);color:var(--accent);display:grid;place-items:center;}
.tool-tile strong{font-size:13px;font-weight:600;line-height:1.5;display:block;}
.tool-tile small{display:block;font-size:11px;line-height:1.65;margin-top:6px;color:var(--muted);}
.tool-note{display:flex;align-items:flex-start;gap:5px;font-size:10px;line-height:1.6;color:var(--muted);margin-top:9px;}
.tool-note .icon{margin-top:2px;flex-shrink:0;}
.tool-entry:has(.tool-unavailable) .tool-tile{height:auto;opacity:.65;}
.tool-unavailable{display:block;font-size:11px;padding:0 15px 14px;color:var(--muted);line-height:1.6;}
.tool-safety{display:flex;align-items:flex-start;gap:13px;margin-top:28px;border:1px solid var(--line-soft);border-radius:12px;background:var(--side);padding:18px 20px;}
.tool-safety>span{color:var(--accent);padding-top:2px;}
.tool-safety strong{font-size:12px;}
.tool-safety p{font-size:11px;color:var(--muted);line-height:1.8;margin-top:5px;max-width:95ch;}
.tools-empty{margin:25px 0;}
@media(max-width:1250px){
 .layout .unified-topbar{grid-template-columns:minmax(0,1fr);gap:8px;padding-block:10px;}
 .unified-topbar .top-actions{width:100%;}
 .unified-topbar .search{flex:1;width:auto;max-width:none;}
 .library .library-actions{max-width:60%;}
 .library-row-main{grid-template-columns:minmax(150px,1fr) 140px;gap:10px;}
 .library-row-actions{grid-column:1/-1;justify-content:flex-end;border-top:1px solid var(--line-soft);padding-top:6px;}
 .library-row-actions .row-open{margin-right:auto;}
}
@media(max-width:980px){
 .task-focus.focus-panel.quiet-focus{grid-template-columns:minmax(0,1fr) 180px;}
 .task-focus.quiet-focus .focus-intro{padding:22px;}
 .task-focus .world-window{min-height:158px;height:158px;}
 .task-focus .world-window-label strong{font-size:18px;}
 .resume-available{display:none;}
 .library .section-heading{flex-direction:column;gap:12px;}
 .library .library-actions{max-width:100%;justify-content:flex-start;}
 .desk-revisit{gap:13px;}
 .task-focus .focus-footer{flex-wrap:wrap;gap:12px;}
 .task-focus .scope-note{margin-left:0;}
}
@media(max-width:820px){
 .layout .unified-topbar{display:flex;flex-direction:row;align-items:flex-start;gap:10px;padding:12px 17px;}
 .unified-topbar .topbar-left{flex:0 0 32px;min-width:0;padding-top:4px;}
 .unified-topbar .owner-badge,.unified-topbar .sample-label{display:none;}
 .unified-topbar .top-actions{flex:1;display:flex;flex-wrap:wrap;justify-content:flex-start;gap:7px;}
 .unified-topbar .search{flex:1 0 100%;min-width:0;height:37px;}
 .main-inner{padding:18px 20px 26px;}
 .library{scroll-margin-top:143px;}
}
@media(max-width:620px){
 .task-focus.focus-panel.quiet-focus{grid-template-columns:minmax(0,1fr);}
 .task-focus.quiet-focus .focus-agenda{padding:0 21px 19px;}
 .task-focus .world-window{height:90px;min-height:90px;}
 .task-focus .world-window-label{padding:10px 13px;}
 .task-focus .world-window-label strong{font-size:20px;}
 .focus-quiet-note{display:none!important;}
 .desk-revisit{grid-template-columns:1fr;}
 .library-controls{flex-wrap:wrap;align-items:center;}
 .library-controls>.tabs{max-width:100%;}
 .library-controls>.view-tools{flex:1;justify-content:flex-end;}
 .library-orientation{align-items:flex-start;}
 .library-orientation .quiet{padding:4px;}
 .breadcrumbs .crumb{max-width:180px;}
 .parent-link{display:none;}
 .cards.list .library-row-main{grid-template-columns:minmax(0,1fr);padding:12px;gap:11px;}
 .row-counts{grid-template-columns:repeat(3,minmax(0,1fr));text-align:left;padding-left:64px;}
 .row-counts span{display:flex;gap:5px;align-items:baseline;font-size:12px;}
 .row-counts small{margin:0;}
 .library-row-actions{grid-column:auto;}
 .cards.list .library-row-preview{padding:12px 14px;}
 .list-meta{gap:5px;}
 .library-row-actions .icon-button{width:34px;flex-basis:34px;}
 .tools-spotlight{padding:12px;gap:7px;}
 .tool-category{font-size:11px;padding:7px 9px;}
 .tools-group-heading{gap:4px;flex-direction:column;}
 .tools-grid{grid-template-columns:minmax(0,1fr);}
}
@media(max-width:410px){
 .main-inner{padding:15px 12px 24px;}
 .layout .unified-topbar{padding:10px 11px;gap:6px;}
 .unified-topbar .top-actions{gap:5px;}
 .unified-topbar :is(.add-cards-top,.browse-top,.sync-top){padding:8px 9px;font-size:11px;gap:5px;height:36px;min-height:36px;}
 .unified-topbar :is(.add-cards-top,.browse-top,.sync-top)>svg{display:none;}
 .unified-topbar :is(.refresh-library,[data-action="appearance"]){height:33px;width:29px;flex:0 0 29px;}
 .task-focus.quiet-focus .focus-intro{padding:20px!important;}
 .task-focus.quiet-focus h1{font-size:27px;}
 .task-focus .focus-footer{padding:12px 19px!important;}
 .task-focus .focus-metric{gap:6px;padding-right:11px;}
 .task-focus .focus-metric strong{font-size:21px;}
 .task-focus .focus-metric span{font-size:9px;}
 .task-focus .scope-note{width:100%;}
 .task-focus .focus-actions .quiet{padding-left:0;}
 .library .section-heading h2{font-size:21px;}
 .library-orientation{gap:6px;}
 .library-orientation>span{font-size:10px;}
 .library-orientation>span>svg{display:none;}
 .row-counts{padding-left:0;justify-content:space-between;gap:6px;}
}
:host([data-density="compact"]) .cards.list .library-row-main{padding-block:9px;}
:host([data-motion="off"]) :is(.tool-tile,.library-row,.revisit-row button),
:host([data-companion="true"]) .task-focus{transition:none;}
@media(prefers-reduced-motion:reduce){.task-focus *, .tools-page *, .library *{transition:none!important;animation:none!important;scroll-behavior:auto!important;}}
/* Match the specificity of the existing world composition, keeping its art/font/radius. */
:host([data-owner="atelier"]) .task-focus.quiet-focus{grid-template-columns:minmax(0,1fr) minmax(210px,27%);}
:host([data-owner="atelier"]) .task-focus.quiet-focus .focus-intro{display:block;padding:25px 27px 23px;}
:host([data-owner="atelier"]) .task-focus.quiet-focus h1{font-size:clamp(26px,2.5vw,36px);line-height:1.13;letter-spacing:-.8px;max-width:none;margin:0;text-wrap:pretty;}
:host([data-owner="atelier"]) .task-focus.quiet-focus .focus-intro>p{margin-top:12px;font-size:13px;line-height:1.6;max-width:60ch;}
:host([data-owner="atelier"]) .task-focus .focus-actions{margin-top:17px;}
:host([data-owner="atelier"]) .task-focus .focus-agenda{display:flex;flex-direction:column;padding:21px 22px 20px 0;}
:host([data-owner="atelier"]) .cards.list .library-row .card-title{font-family:"Segoe UI",system-ui,sans-serif;font-weight:600;}
:host([data-owner="atelier"]) .tools-heading h1{font-family:var(--world-font);}
@media(max-width:980px){
 :host([data-owner="atelier"]) .task-focus.quiet-focus{grid-template-columns:minmax(0,1fr) 180px;}
 :host([data-owner="atelier"]) .task-focus.quiet-focus .focus-intro{padding:22px;}
}
@media(max-width:620px){
 :host([data-owner="atelier"]) .task-focus.quiet-focus{grid-template-columns:minmax(0,1fr);}
 :host([data-owner="atelier"]) .task-focus .focus-agenda{padding:0 21px 19px;}
 :host([data-owner="atelier"]) .task-focus.quiet-focus h1{font-size:27px!important;}
}
@media(forced-colors:active){
 .tool-entry,.library-row,.resume-lecture,.revisit-column,.library-orientation{border:1px solid CanvasText;}
 .tool-category.selected,.list-meta .focus-badge{outline:1px solid Highlight;}
 .tool-symbol,.resume-glyph,.revisit-glyph{color:ButtonText;}
}
/* A leaf deck is a study destination, not an empty-folder dead end. */
.deck-detail{border:1px solid var(--line);border-radius:var(--world-radius,18px);background:var(--panel);padding:26px;}
.deck-detail-head{display:flex;align-items:center;gap:16px;}
.detail-glyph{width:46px;flex:0 0 46px;color:var(--tone);}
.detail-glyph svg{width:46px;height:44px;}
.deck-detail h3{font-size:20px;letter-spacing:-.35px;line-height:1.3;}
.deck-detail-head p{font-size:12px;line-height:1.7;color:var(--muted);margin-top:7px;}
.deck-detail-counts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-top:25px;border-block:1px solid var(--line-soft);padding:18px 0;}
.deck-detail-counts strong{display:block;font-size:27px;font-weight:500;font-variant-numeric:tabular-nums;line-height:1.3;}
.deck-detail-counts span{display:block;font-size:11px;color:var(--muted);margin-top:5px;}
.deck-detail-actions{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin-top:21px;}
.deck-detail-actions button{min-height:38px;font-size:12px;}
.detail-note{display:flex;align-items:flex-start;gap:8px;font-size:11px;line-height:1.7;color:var(--muted);margin-top:20px;}
.detail-note .icon{margin-top:2px;}
@media(max-width:500px){.deck-detail{padding:19px}.deck-detail h3{font-size:19px}.deck-detail-head{gap:11px}.detail-glyph{width:34px;flex-basis:34px}.detail-glyph svg{width:34px}.deck-detail-counts{gap:10px}.deck-detail-counts span{font-size:10px}.deck-detail-counts strong{font-size:25px}}

/* One read-only authoring projection; actions open the single source workspace. */
.authoring-hub{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:18px;padding:24px;margin:22px 0;border:1px solid var(--line);border-radius:18px;background:var(--panel);}
.authoring-hub h2{font-size:21px;letter-spacing:-.4px;}.authoring-hub .eyebrow{font-size:9px;margin-bottom:7px;}.authoring-hub p{font-size:12px;color:var(--muted);margin-top:7px;}
.authoring-hub-actions{display:flex;flex-wrap:wrap;gap:8px;}.authoring-hub-actions button{font-size:12px;min-height:38px;}
@media(max-width:640px){.authoring-hub{padding:18px}.authoring-hub-actions{width:100%}.authoring-hub-actions button{flex:1;min-width:120px;}}

.widget-presets{display:grid;gap:12px;padding:18px;border:1px solid var(--line);border-radius:14px;background:var(--raised);margin-bottom:20px;}.widget-presets small{display:block;color:var(--muted);font-size:12px;line-height:1.6;margin-top:5px;}.widget-presets>div:last-child{display:flex;gap:8px;flex-wrap:wrap;}.widget-presets [aria-pressed="true"]{outline:2px solid var(--accent);outline-offset:2px;}

/* rc3 usability audit: unfinished work is a task queue, not another hero. */
.workflow-inbox{margin:0 0 20px;padding:14px 16px;border:1px solid var(--line-soft);border-radius:16px;background:var(--side);color:var(--text);}
.workflow-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;}
.workflow-heading>strong{font-size:13px;letter-spacing:0;}
.workflow-heading .quiet{font-size:12px;min-height:34px;}
.workflow-inbox>p{font-size:12px;color:var(--muted);margin:8px 0 0;line-height:1.65;}
.workflow-items{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,225px),1fr));gap:8px;margin-top:10px;}
.workflow-item{display:flex;align-items:center;gap:10px;padding:10px 12px;border:1px solid var(--line);border-radius:11px;background:var(--panel);color:var(--text);text-align:left;min-width:0;min-height:58px;}
.workflow-item>span:nth-child(2){flex:1;min-width:0;}
.workflow-item strong{font:600 12px/1.4 "Segoe UI",system-ui,sans-serif;display:block;}
.workflow-item small{display:block;font-size:11px;color:var(--muted);line-height:1.5;overflow-wrap:anywhere;}
.workflow-item:hover{background:var(--raised);border-color:var(--accent);transform:none;}
.workflow-glyph{color:var(--accent);display:grid;place-content:center;flex:0 0 22px;}
.practice-plan-picker{display:grid;gap:10px;}
.practice-plan-picker>button{display:flex;align-items:center;gap:12px;width:100%;padding:14px;border:1px solid var(--line);border-radius:12px;background:var(--panel);color:var(--text);}
.practice-plan-picker>button>span:nth-child(2){flex:1;min-width:0;text-align:left;}
.practice-plan-picker strong,.practice-plan-picker small{display:block;overflow-wrap:anywhere;}
.practice-plan-picker small{margin-top:4px;color:var(--muted);font-size:12px;}
.practice-plan-picker>button:hover{background:var(--raised);border-color:var(--accent);}

/* Functional labels must be readable without zooming into decorative metadata. */
.side-utilities button,.side-quick button,.scope-bar .quiet,.scope-bar>span:first-child,.scope-bar select,.library-actions .quiet,.library-actions .secondary,.parent-link,.exam-section-actions .quiet,.help-strip .quiet,.library-controls :is(select,button),.peek-more,.tree-open,.nav-group .nav-row,.side-links button{font-size:13px!important;line-height:1.5!important;}
.library-foot,.countline,.card-description,.card-path,.scope-note,.row-counts small,.lecture-counts small,.note{font-size:12px!important;line-height:1.5!important;}
.focus-card{grid-template-columns:minmax(0,1fr) minmax(230px,32%)!important;}.focus-agenda{min-width:0;}.focus-intro{min-width:0;}
@media(max-width:850px){.focus-card{grid-template-columns:minmax(0,1fr)!important}}

/* Release finish: same bounded, accessible dialog system for progress/export. */
.export-controls,.progress-controls{display:flex;align-items:flex-end;gap:12px;flex-wrap:wrap;margin-bottom:18px}
.export-controls label,.progress-controls label{display:grid;gap:8px;font-size:13px;font-weight:600;min-width:0;flex:1 1 150px}
.export-controls label:first-child{flex:3 1 240px}
.export-controls input,.export-controls select,.progress-controls select{width:100%;min-height:42px;font-size:14px}
.export-list{display:grid;gap:8px;margin:12px 0 18px}
.export-row{display:flex;align-items:center;gap:13px;width:100%;min-width:0;min-height:74px;padding:14px;border:1px solid var(--line);border-radius:12px;background:var(--panel)}
.export-row:hover{border-color:var(--accent);background:var(--raised)}
.export-row>span:nth-child(2){flex:1;min-width:0;display:grid;gap:5px}
.export-row strong{font-size:14px;overflow-wrap:anywhere}.export-row small{font-size:12px;line-height:1.4;color:var(--muted);overflow-wrap:anywhere}
.export-icon{flex:0 0 36px;display:grid;place-content:center;color:var(--accent)}
.progress-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:12px 0 24px}
.progress-summary>div{display:grid;gap:10px;padding:16px 12px;border:1px solid var(--line);border-radius:14px;background:var(--panel)}
.progress-summary strong{font-size:26px;letter-spacing:-.6px;font-variant-numeric:tabular-nums;line-height:1.2}
.progress-summary span{font-size:12px;line-height:1.4;color:var(--muted)}
.progress-chart{padding:18px 14px 12px;background:var(--panel);border:1px solid var(--line);border-radius:16px;margin-bottom:18px;overflow-x:auto}
.progress-bars{display:flex;gap:6px;align-items:stretch;height:165px;min-width:240px}
.progress-day{flex:1;min-width:5px;display:flex;flex-direction:column;justify-content:flex-end;align-items:stretch;position:relative;padding-bottom:24px}
.progress-day>div{height:var(--bar-height);max-height:140px;min-height:2px;background:linear-gradient(0deg,var(--accent-soft),var(--accent));border-radius:5px 5px 2px 2px}
.progress-day small{position:absolute;bottom:0;left:50%;transform:translateX(-50%);font-size:10px;color:var(--muted);white-space:nowrap}
.progress-bars:has(.progress-day:nth-child(8)) .progress-day small{display:none}
.progress-bars:has(.progress-day:nth-child(8)) .progress-day:first-child small,.progress-bars:has(.progress-day:nth-child(8)) .progress-day:last-child small{display:block}
.progress-detail{border:1px solid var(--line);border-radius:12px;padding:14px;margin:16px 0;overflow-x:auto;font-size:13px;line-height:1.7}
.progress-detail summary{cursor:pointer;font-weight:600}.progress-detail table{width:100%;border-collapse:collapse;margin:14px 0;text-align:right;font-variant-numeric:tabular-nums}
.progress-detail th,.progress-detail td{padding:8px;border-bottom:1px solid var(--line-soft);font-size:12px;white-space:nowrap}.progress-detail th:first-child,.progress-detail td:first-child{text-align:left}
.progress-deck-title{font-size:17px;margin:22px 0 12px}.progress-decks{display:grid;gap:8px;margin-bottom:18px}
.progress-decks>div{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:6px 16px;border-bottom:1px solid var(--line-soft);padding:12px 0;font-size:13px}
.progress-decks span{overflow-wrap:anywhere}.progress-decks strong{font-variant-numeric:tabular-nums}.progress-decks small{grid-column:2;color:var(--muted)}
@media(max-width:600px){.progress-summary{grid-template-columns:repeat(2,minmax(0,1fr))}.export-controls,.progress-controls{gap:10px}.progress-summary strong{font-size:24px}}
@media(prefers-reduced-motion:reduce){.export-row{transition:none}}
/* Real control classes (not only their container aliases): keep essentials readable. */
.recent-link,.native-link{font-size:13px!important;line-height:1.5!important;min-height:32px;}

web/native-widgets.css:
/* Owned ShadowRoot only. Provider/card/media DOM is never sized by these rules. */
.layout[data-page="widgets"] .main-inner{max-width:1280px;padding:24px clamp(18px,3vw,42px) 36px;margin:0 auto;width:100%;}
.layout[data-page="widgets"] .nw-header{height:auto;min-height:94px;padding:22px clamp(18px,3vw,42px);gap:16px;display:flex;align-items:center;justify-content:space-between;}
.nw-header-title{display:flex;gap:15px;align-items:center;min-width:0;}
.nw-header-title small{display:block;color:var(--muted);font-size:12px;letter-spacing:.5px;margin-bottom:5px;}
.nw-header-title h1{font-family:var(--world-font);font-size:30px;line-height:1.15;letter-spacing:-.7px;color:var(--text);}
.nw-header-controls{display:flex;align-items:center;gap:10px;flex-shrink:0;}
.nw-header-controls .icon-button{height:40px;width:40px;}
.native-widgets{min-width:0;}
.nw-toolbar{display:flex;align-items:center;flex-wrap:wrap;gap:10px;padding:0 0 24px;border-bottom:1px solid var(--line);}
.nw-toolbar .primary,.nw-toolbar .secondary,.nw-toolbar .quiet{min-height:42px;font-size:14px;display:inline-flex;align-items:center;gap:8px;}
.nw-toolbar .quiet{margin-left:8px;}
.nw-section-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:24px 0 16px;color:var(--muted);font-size:13px;line-height:1.5;}
.nw-section-heading h2{color:var(--text);font-size:20px;}
.nw-section-heading>span{font-size:12px;}
.nw-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;align-items:start;}
.nw-card{min-width:0;background:linear-gradient(135deg,var(--panel),var(--side));border:1px solid var(--line);border-radius:var(--world-radius,20px);padding:22px 24px 0;box-shadow:inset 0 1px 0 var(--sheen,rgba(255,255,255,.05)),0 10px 28px var(--shadow);overflow:hidden;}
.nw-wide{grid-column:1/-1;}
.nw-card[data-native-widget="today"]{background:linear-gradient(112deg,var(--hero),var(--hero-end));}
.nw-card-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:20px;min-width:0;}
.nw-title-mark{display:flex;align-items:center;gap:10px;min-width:0;}
.nw-title-mark>.icon{color:var(--accent);}
.nw-title-mark h2{font-family:"Segoe UI",system-ui,sans-serif;font-size:16px;font-weight:650;line-height:1.4;letter-spacing:-.2px;overflow-wrap:anywhere;}
.nw-caption{font-size:12px;color:var(--muted);line-height:1.5;max-width:50%;text-align:right;overflow-wrap:anywhere;}
.nw-today-content{display:grid;grid-template-columns:minmax(0,1fr) minmax(180px,28%);gap:32px;align-items:center;}
.nw-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;}
.nw-metrics strong{display:block;font-family:"Segoe UI",system-ui,sans-serif;font-weight:550;font-size:38px;font-variant-numeric:tabular-nums;letter-spacing:-1px;line-height:1.3;}
.nw-metrics span{display:block;color:var(--muted);font-size:12px;line-height:1.4;margin-top:6px;}
.nw-definitions{color:var(--muted);font-size:12px;line-height:1.65;max-width:570px;margin:18px 0 4px;}
.nw-week{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:8px;height:98px;}
.nw-day{position:relative;display:flex;align-items:flex-end;justify-content:center;border-bottom:1px solid var(--line);padding-bottom:17px;}
.nw-day>span{height:calc(var(--level)*.72);min-height:3px;width:70%;max-width:24px;border-radius:4px 4px 0 0;background:var(--accent);opacity:.45;}
.nw-day.is-today>span{opacity:1;}
.nw-day small{font-size:10px;line-height:12px;position:absolute;bottom:0;color:var(--muted);}
.nw-link-list{min-width:0;}
.nw-focus-row{display:flex;align-items:center;gap:4px;border-top:1px solid var(--line-soft);}
.nw-focus-row:first-child{border-top:0;}
.nw-focus-row .icon-button{flex:0 0 32px;height:32px;width:32px;color:var(--muted);}
.nw-open{display:flex;align-items:center;gap:12px;min-width:0;flex:1;width:100%;padding:12px 2px;border-radius:7px;color:var(--text);font-size:14px;}
.nw-open:hover{background:var(--hover);}
.nw-open>span:not(.nw-date):not(.nw-dot){display:block;flex:1;min-width:0;}
.nw-open strong{display:block;font-size:14px;line-height:1.5;font-weight:600;overflow-wrap:anywhere;}
.nw-open small{display:block;font-size:12px;line-height:1.5;color:var(--muted);margin-top:4px;overflow-wrap:anywhere;}
.nw-dot{height:6px;width:6px;flex:0 0 6px;border-radius:50%;background:var(--accent);}
.nw-date{display:grid;place-items:center;flex:0 0 36px;height:36px;color:var(--accent);background:var(--accent-soft);border-radius:10px;}
.nw-plan+.nw-plan{border-top:1px solid var(--line-soft);}
.nw-card-footer{border-top:1px solid var(--line-soft);margin:18px -24px 0;padding:10px 16px;display:flex;align-items:center;gap:8px;flex-wrap:wrap;min-height:52px;background:var(--material,transparent);}
.nw-card-footer .quiet{display:inline-flex;align-items:center;gap:7px;font-size:13px;min-height:34px;padding:5px 8px;}
.nw-card-footer .nw-caption{margin-left:auto;}
.nw-work-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px;}
.nw-work-link{display:flex;align-items:center;gap:12px;padding:12px;background:var(--raised);border:1px solid var(--line-soft);border-radius:12px;min-height:76px;}
.nw-work-link>.icon{color:var(--accent);}
.nw-work-link>span{min-width:0;}
.nw-work-link strong,.nw-work-empty strong{display:block;font-size:14px;font-weight:600;line-height:1.5;}
.nw-work-link small,.nw-work-empty small{display:block;font-size:12px;color:var(--muted);line-height:1.6;margin-top:4px;}
.nw-work-empty{padding:12px;border:1px dashed var(--line);border-radius:12px;}
.nw-state{font-size:14px;line-height:1.8;color:var(--muted);margin:10px 0 24px;overflow-wrap:anywhere;}
.nw-empty{grid-column:1/-1;padding:38px 26px;background:var(--panel);border:1px dashed var(--line);border-radius:20px;text-align:center;}
.nw-empty h2{font-size:24px;margin:0 0 10px;}
.nw-empty p{font-size:14px;line-height:1.7;margin:10px auto 20px;color:var(--muted);max-width:480px;}
.nw-empty .primary{display:inline-flex;align-items:center;gap:8px;}
.nw-bottom-note{color:var(--quiet);font-size:12px;line-height:1.65;margin:20px 0 0;}
.nw-on-home{margin:20px 0 28px;}
.nw-note-text{white-space:pre-wrap;font-size:15px;line-height:1.8;overflow-wrap:anywhere;max-height:300px;overflow:auto;margin:4px 0 18px;}
.nw-note-label{display:block;font-weight:600;line-height:1.6;}
#nw-note-input{box-sizing:border-box;display:block;width:100%;max-width:100%;min-height:180px;max-height:50vh;resize:vertical;background:var(--panel);border:1px solid var(--line);border-radius:10px;color:var(--text);font:15px/1.7 "Segoe UI",system-ui,sans-serif;padding:14px;margin-top:10px;}
.nw-arranged-list{display:grid;gap:10px;}
.nw-arranged{display:flex;align-items:center;gap:12px;flex-wrap:wrap;border:1px solid var(--line);border-radius:12px;background:var(--panel);padding:12px;}
.nw-arranged-label{flex:1;min-width:120px;}
.nw-arranged-label strong{display:block;font-size:14px;overflow-wrap:anywhere;}
.nw-arranged-label small{display:block;font-size:11px;line-height:1.6;color:var(--muted);margin-top:4px;}
.nw-arranged-options{display:flex;gap:14px;align-items:center;flex-wrap:wrap;}
.nw-arranged-options label{display:flex;align-items:center;gap:7px;font-size:12px;line-height:1.5;}
.nw-arranged-options select{font-size:12px;padding:6px 8px;}
.nw-arranged-move{display:flex;gap:2px;}
.nw-arranged-move .icon-button{width:32px;height:34px;}
.nw-add-heading{font-size:16px;margin:24px 0 14px;}
.nw-catalog{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;}
.nw-catalog-item{display:flex;gap:12px;align-items:center;background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:14px;min-width:0;}
.nw-catalog-item>.icon{color:var(--accent);}
.nw-catalog-item>span{flex:1;min-width:0;}
.nw-catalog-item strong{font-size:14px;display:block;line-height:1.5;overflow-wrap:anywhere;}
.nw-catalog-item small{font-size:12px;display:block;color:var(--muted);line-height:1.6;margin-top:5px;}
.nw-provider-help{font-size:13px;line-height:1.75;margin-top:22px;color:var(--muted);}
.nw-provider-help summary{cursor:pointer;}
.nw-provider-help p{margin-top:10px;}
.nw-tools-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;}
.nw-tool{display:flex;align-items:center;gap:12px;font-size:14px;min-height:46px;padding:12px;border:1px solid var(--line-soft);background:var(--panel);border-radius:10px;}
.nw-tool:hover,.nw-catalog-item:hover{border-color:var(--accent);background:var(--raised);}
.nw-tool>.icon{color:var(--accent);}
.nw-card [data-native-provider]{display:block;min-width:0;max-width:100%;padding-bottom:22px;}
.nw-card:not(.nw-wide) .nw-today-content{grid-template-columns:1fr;gap:18px;}
.nw-card:not(.nw-wide) .nw-metrics{gap:10px;}
.nw-card:not(.nw-wide) .nw-metrics strong{font-size:30px;}
@media(max-width:1100px){.nw-today-content{grid-template-columns:1fr;gap:16px}.nw-week{height:68px;max-width:360px}.nw-grid{gap:14px}.nw-metrics strong{font-size:32px}.nw-card{padding:18px 18px 0}.nw-card-footer{margin-left:-18px;margin-right:-18px}.nw-caption{max-width:44%}}
@media(max-width:760px){.nw-grid{grid-template-columns:minmax(0,1fr)}.nw-card-heading{flex-wrap:wrap}.nw-caption{max-width:100%;text-align:left}.layout[data-page="widgets"] .nw-header{flex-wrap:wrap;min-height:0;padding-top:16px;padding-bottom:16px}.nw-header-title h1{font-size:26px}.nw-header-controls{margin-left:auto}.nw-section-heading>span{display:none}.nw-catalog{grid-template-columns:1fr}.nw-tools-list{grid-template-columns:1fr}.nw-arranged{gap:10px}.nw-arranged-label{min-width:130px}.nw-arranged-options{order:3;width:100%}.nw-toolbar .quiet{margin-left:0}.nw-card-footer .nw-caption{margin-left:0}.nw-metrics span{font-size:12px}.nw-header-controls .secondary{font-size:13px;padding:8px 10px}.nw-header-title small{display:none}}
@media(prefers-reduced-motion:reduce){.native-widgets *, .nw-on-home *{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
:host([data-motion="off"]) .native-widgets *, :host([data-motion="off"]) .nw-on-home *{animation:none!important;transition:none!important}
@media(forced-colors:active){.nw-card,.nw-catalog-item,.nw-tool,.nw-arranged{border:1px solid CanvasText}.nw-day>span,.nw-dot{background:Highlight}.nw-date{color:CanvasText}}

web/review-finish.css:
/* Reader-first finish. No sizing, wrapping, transforms or card selectors added. */
html[data-atelier-screen="review"] #atelier-review-header button:focus-visible,
html[data-atelier-screen="review-bottom"][data-atelier-toolbar="stock"] #outer button:focus-visible{outline:2px solid var(--at-accent-strong)!important;outline-offset:3px!important;box-shadow:0 0 0 2px var(--at-side)!important;}
html[data-atelier-screen="review-bottom"][data-atelier-toolbar="stock"] #outer button{transition:background-color .14s ease,border-color .14s ease!important;transform:none!important;}
html[data-atelier-motion="off"][data-atelier-screen="review-bottom"] #outer button{transition:none!important;}
@media(prefers-reduced-motion:reduce){html[data-atelier-screen="review-bottom"] #outer button{transition:none!important;}}
@media(forced-colors:active){html[data-atelier-screen="review-bottom"] #outer button:focus-visible{outline:2px solid Highlight!important;box-shadow:none!important;}}

