/* Presentation only. Layout-only bridge; no answer handlers, template edits, scheduling or keys. */
(() => {
  'use strict';
  const start=()=>{
    const boot=document.getElementById('atelier-review-boot');
    if(!boot||window.AtelierReview)return;
    let config;try{config=JSON.parse(boot.textContent);}catch(_){return;}
    const root=document.documentElement;
    let lastGeometry='', geometryTimer=null, observedOuter=null, footerObserver=null;
    let info=window.__atelierReviewCard||{eligible:false,path:[],stage:'question'},header=null,scheduled=false,resetQuestion=false;
    let gapOriginal=null,gapNode=null,qaSizeObserver=null,observedQA=null,alignFrame=0,settleUntil=0,userMoved=false,paintKey='',disposed=false;
    const keyOf=x=>String(x?.id||'')+':'+String(x?.stage||'question');
    // Keep all flags/classes/styles owned by the card and every node in #qa.
    // Advanced/IO layouts retain their exact canvas and image geometry.
    function complexContent(){
      const qa=document.getElementById('qa');
      if(!qa)return true;
      return info.protected===true || !!qa.querySelector('canvas,iframe,object,embed,#image-occlusion-container,#image-occlusion-canvas,[id^=io-],[id^=io_],[data-occlusions],.io-overlay,.io-wrapper,.io-mask,.image-occlusion') || /(?:image.occlusion|io[-_](?:overlay|wrapper|qmask|amask|original|container))/i.test(qa.innerHTML) || [...qa.querySelectorAll('[style]')].some(e=>/position\s*:\s*(absolute|fixed|sticky)|transform\s*:|zoom\s*:/.test(e.getAttribute('style')||''));
    }
    function imageOcclusion(){
      if(info.protected===true)return false;
      const qa=document.getElementById('qa');
      return !!qa?.querySelector('#image-occlusion-container,#image-occlusion-canvas,#io-wrapper,#io-overlay,[data-occlusions],.io-wrapper,.io-overlay') || info.imageOcclusion===true;
    }
    // Only own #qa's top gap for eligible reading cards; never resize, wrap or
    // transform the original image/canvas/masks. Restore the latest foreign value.
    function releaseGap(){
      if(gapNode&&gapOriginal&&gapNode.style.getPropertyValue('margin-top')===gapOriginal.applied&&gapNode.style.getPropertyPriority('margin-top')==='important'){
        if(gapOriginal.value)gapNode.style.setProperty('margin-top',gapOriginal.value,gapOriginal.priority);else gapNode.style.removeProperty('margin-top');
      }
      gapNode=null;gapOriginal=null;
    }
    function ownGap(qa){
      if(gapNode!==qa){releaseGap();gapNode=qa;}
      const v=qa.style.getPropertyValue('margin-top'),p=qa.style.getPropertyPriority('margin-top'),desired=config.context==='hidden'?'auto':'0px';
      if(gapOriginal&&v===gapOriginal.applied&&p==='important'){if(v!==desired){qa.style.setProperty('margin-top',desired,'important');gapOriginal.applied=desired;}return;}
      gapOriginal={value:v,priority:p,applied:desired};qa.style.setProperty('margin-top',desired,'important');
    }
    function observeSize(qa){
      if(observedQA===qa)return;
      qaSizeObserver?.disconnect();observedQA=qa;
      if(qa&&window.ResizeObserver){qaSizeObserver=new ResizeObserver(scheduleLayout);qaSizeObserver.observe(qa);}
    }
    function settleLayout(){
      alignFrame=0;
      if(disposed||config.screen!=='review'||root.dataset.atelierCard!=='reading')return;
      const qa=document.getElementById('qa');if(!qa)return;
      ownGap(qa);observeSize(qa);
      const clearance=Math.max(0,Number(window.onigiriReviewerHeaderOffsetPx)||0);
      const v=clearance+'px';if(root.style.getPropertyValue('--atelier-header-clearance')!==v)root.style.setProperty('--atelier-header-clearance',v);
      const st=getComputedStyle(document.body),qr=qa.getBoundingClientRect();
      const hr=header?.isConnected?header.getBoundingClientRect():null;
      const pad=parseFloat(st.paddingTop)+parseFloat(st.paddingBottom);
      const total=qr.height+(hr?hr.height+10:0)+pad;
      root.dataset.atelierFit=total<=innerHeight+1?'fits':'scroll';
      // Counter Anki's delayed answer scroll ONLY when the whole reading card fits.
      // Long answers retain native answer-anchor scrolling and manual scrolling wins.
      if(!userMoved && performance.now()<settleUntil && (resetQuestion||total<=innerHeight+1)){
        window.scrollTo({top:0,left:0,behavior:'instant'});resetQuestion=false;
      }
    }
    function scheduleLayout(){if(!alignFrame&&!disposed)alignFrame=requestAnimationFrame(settleLayout);}
    function newPaint(value){
      const key=keyOf(value);if(key!==paintKey){paintKey=key;userMoved=false;settleUntil=performance.now()+1600;resetQuestion=value?.stage==='question';if(header){header.dataset.expanded='false';const b=header.querySelector('button');if(b){b.setAttribute('aria-expanded','false');b.textContent='Details';}}}
      info=value||{eligible:false,path:[]};queue();scheduleLayout();
    }
    function stockFooter(){
      const outer=document.getElementById('outer'),table=document.getElementById('innertable'),middle=document.getElementById('middle');
      if(!outer||!table||!middle||!outer.contains(table)||!table.contains(middle))return false;
      // A replacement bar owns its own sizing. Fail closed when the native
      // three-cell row is no longer present, rather than breaking its layout.
      const row=table.tBodies[0]?.rows[0];
      return !!row && row.cells.length>=3 && Array.from(row.cells).includes(middle) &&
        row.cells[0].classList.contains('stat') && row.cells[row.cells.length-1].classList.contains('stat');
    }
    function measureFooter(){
      if(config.screen!=='review-bottom'||config.style==='off'||!stockFooter())return null;
      const outer=document.getElementById('outer'),r=outer.getBoundingClientRect();
      const height=Math.ceil(Math.max(r.height,outer.scrollHeight)+Math.max(0,r.top)+2);
      return {token:config.layoutToken,height,width:root.clientWidth,version:config.version||'1.0.2'};
    }
    function requestFooterFit(force=false){
      if(config.screen!=='review-bottom')return;
      clearTimeout(geometryTimer);
      geometryTimer=setTimeout(()=>{
        const outer=document.getElementById('outer');
        if(!outer)return;
        const key=[Math.ceil(outer.getBoundingClientRect().height),document.documentElement.clientWidth,window.innerHeight,root.dataset.atelierToolbar||'native',config.style].join(':');
        if(key===lastGeometry&&!force)return;lastGeometry=key;
        if(typeof window.pycmd==='function'&&config.layoutToken){
          window.pycmd('atelier:review-layout:'+config.layoutToken);
        }
        // Offline preview listens here; native Anki receives the guarded measurement.
        window.dispatchEvent(new CustomEvent('atelier:review-layout',{detail:{height:Math.ceil(outer.getBoundingClientRect().bottom)+4}}));
      },60);
    }
    function footer(){
      if(config.screen!=='review-bottom')return;
      const stock=stockFooter();
      if(stock){root.dataset.atelierToolbar='stock';root.dataset.atelierExtraCells=String(document.getElementById('innertable').tBodies[0].rows[0].cells.length>3);}else{delete root.dataset.atelierToolbar;delete root.dataset.atelierExtraCells;}
      const outer=document.getElementById('outer');
      if(outer!==observedOuter&&window.ResizeObserver){footerObserver?.disconnect();observedOuter=outer;if(outer){footerObserver=new ResizeObserver(()=>requestFooterFit());footerObserver.observe(outer);}}
      requestFooterFit();
    }
    function update(){
      scheduled=false;
      const enabled=config.style!=='off';
      if(!enabled){releaseGap();observeSize(null);delete root.dataset.atelierFit;delete root.dataset.atelierScreen;delete root.dataset.atelierCard;delete root.dataset.atelierToolbar;header?.remove();header=null;delete root.dataset.atelierContext;requestFooterFit();return;}
      root.dataset.atelierScreen=config.screen;root.dataset.atelierWorld=config.theme;root.dataset.atelierMotion=config.motion?'on':'off';root.dataset.atelierWidth=config.width;root.dataset.atelierAmbience=String(config.ambience!==false);root.dataset.atelierContext=['compact','full','hidden'].includes(config.context)?config.context:'compact';
      if(config.screen==='review-bottom'){footer();return;}
      if(config.screen!=='review')return;
      const reading=config.style==='adaptive'&&info.eligible===true&&!complexContent();
      root.dataset.atelierCard=reading?'reading':config.style==='adaptive'&&imageOcclusion()?'media':'native';
      if(reading&&config.context!=='hidden'){
        if(!header){
          header=document.createElement('div');header.id='atelier-review-header';
          const label=document.createElement('span');label.className='atelier-review-stage';
          const title=document.createElement('strong');title.className='atelier-review-lecture';
          const path=document.createElement('span');path.className='atelier-review-path';
          const toggle=document.createElement('button');toggle.type='button';toggle.className='atelier-review-details';
          toggle.textContent='Details';toggle.title='Show lecture path';toggle.setAttribute('aria-label','Show lecture path');toggle.setAttribute('aria-expanded','false');
          path.id='atelier-review-path';toggle.setAttribute('aria-controls',path.id);
          toggle.addEventListener('click',()=>{const open=header.dataset.expanded!=='true';header.dataset.expanded=String(open);toggle.setAttribute('aria-expanded',String(open));toggle.textContent=open?'Less':'Details';scheduleLayout();});
          header.append(label,title,toggle,path);
          const qa=document.getElementById('qa');if(qa)qa.before(header);
        }
        const path=Array.isArray(info.path)?info.path.map(String):[];
        if(!header.isConnected){document.getElementById('qa')?.before(header);}
        header.querySelector('.atelier-review-stage').textContent=info.stage==='answer'?'REVEAL & REFLECT':'RECALL';
        header.querySelector('.atelier-review-lecture').textContent=path.at(-1)||'Your study session';
        header.querySelector('.atelier-review-path').textContent=path.slice(0,-1).join('  ›  ');
        header.querySelector('.atelier-review-path').title=path.join(' › ');
      }else{header?.remove();header=null;}
      if(reading){ownGap(document.getElementById('qa'));scheduleLayout();}
      else {resetQuestion=false;releaseGap();observeSize(null);delete root.dataset.atelierFit;}

    }
    const queue=()=>{if(!scheduled){scheduled=true;queueMicrotask(update);}};
    const api={painted:newPaint,settled(value){if(keyOf(value)===keyOf(info)){newPaint(value);scheduleLayout();}},measureFooter,refit:()=>requestFooterFit(true),setCard(value){newPaint(value);},configure(value){config={...config,...value};update();},diagnostics(){return {screen:root.dataset.atelierScreen||'off',card:root.dataset.atelierCard||'native',width:config.width,toolbar:root.dataset.atelierToolbar||'native',context:root.dataset.atelierContext||'original',layout:lastGeometry,version:config.version||'1.0.2',height:measureFooter()?.height||0,viewportHeight:innerHeight,scrollHeight:document.scrollingElement?.scrollHeight,fit:root.dataset.atelierFit||'native',headerClearance:root.style.getPropertyValue('--atelier-header-clearance'),bodyBackground:getComputedStyle(document.body).backgroundColor,controls:[...document.querySelectorAll('#outer button')].map(b=>{const r=b.getBoundingClientRect();return {command:b.getAttribute('onclick')?.match(/(?:ease[1-4]|ans|edit|more)/)?.[0]||'extension',x:r.x,y:r.y,width:r.width,height:r.height};})};}};
    window.AtelierReview=Object.freeze(api);
    const qa=document.getElementById('qa');
    if(qa){new MutationObserver(queue).observe(qa,{childList:true,subtree:true});new MutationObserver(scheduleLayout).observe(qa,{attributes:true,attributeFilter:['style']});}
    if(config.screen==='review-bottom'){
      new MutationObserver(queue).observe(document.body,{childList:true,subtree:true});
      window.addEventListener('resize',()=>requestFooterFit());
      document.fonts?.ready.then(()=>requestFooterFit(true));
    }
    if(config.screen==='review'){
      window.addEventListener('onigiri-reviewer-header-offset',queue);window.addEventListener('resize',queue);
      document.addEventListener('load',scheduleLayout,true);document.fonts?.ready.then(scheduleLayout);
      for(const name of ['wheel','touchmove','pointerdown'])window.addEventListener(name,()=>{userMoved=true;},{passive:true});
      window.addEventListener('keydown',e=>{if(['PageDown','PageUp','ArrowDown','ArrowUp','Home','End'].includes(e.key))userMoved=true;},true);
      window.addEventListener('pagehide',()=>{disposed=true;cancelAnimationFrame(alignFrame);qaSizeObserver?.disconnect();},{once:true});
    }
    update();
  };
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();

web/session-shell.css:
/* Session/results · rc5. Planner only; never styles native card contents. */
#es-app[data-suite="true"] .es-modal {
  width:min(960px,calc(100vw - 36px));max-width:calc(100vw - 36px);max-height:calc(100dvh - 36px);
  margin:auto;padding:0;border:1px solid var(--es-line);border-radius:22px;
  color:var(--es-text);background:var(--es-surface);overflow:hidden;
}
#es-app[data-suite="true"] .es-modal[data-view="results"] {width:min(1100px,calc(100vw - 36px));}
#es-app[data-suite="true"] .es-modal-inner {display:flex;flex-direction:column;max-height:calc(100dvh - 38px);min-height:0;padding:0;}
#es-app[data-suite="true"] .suite-modal-heading {display:flex;align-items:flex-start;gap:16px;justify-content:space-between;flex-shrink:0;padding:24px 28px 18px;border-bottom:1px solid var(--es-line);}
#es-app[data-suite="true"] .suite-modal-heading h2 {font:600 clamp(20px,2.1vw,28px)/1.2 var(--world-font,system-ui);letter-spacing:-.45px;margin:0;overflow-wrap:anywhere;}
#es-app[data-suite="true"] .suite-modal-close {font:24px/1 system-ui;width:36px;min-width:36px;height:36px;padding:0;border-radius:9px;}
#es-app[data-suite="true"] .suite-modal-scroll {flex:1 1 auto;min-height:0;overflow:auto;overscroll-behavior:contain;padding:24px 28px;scrollbar-width:thin;scrollbar-color:var(--es-line) transparent;}
#es-app[data-suite="true"] .es-modal .es-modal-actions {display:flex;flex-wrap:wrap;gap:8px;align-items:center;justify-content:flex-end;flex-shrink:0;margin:0;padding:16px 28px;border-top:1px solid var(--es-line);background:var(--es-surface);}
#es-app[data-suite="true"] .es-modal-actions button {font:500 13px/1.4 system-ui;min-height:40px;white-space:normal;}
#es-app[data-suite="true"] .suite-session-heading {display:flex;flex-wrap:wrap;justify-content:space-between;gap:8px;font:12px/1.5 system-ui;color:var(--es-muted);margin-bottom:16px;}
#es-app[data-suite="true"] .suite-session-kicker {text-transform:uppercase;letter-spacing:1.1px;font-size:10px;font-weight:650;}
#es-app[data-suite="true"] .suite-result-hero {display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:28px;padding:26px;border:1px solid var(--es-line);border-radius:var(--world-radius,18px);background:linear-gradient(120deg,var(--es-soft),var(--es-surface));}
#es-app[data-suite="true"] .suite-result-hero .es-big-score {font:500 clamp(42px,7vw,68px)/1.1 var(--world-font,system-ui);letter-spacing:-2px;color:var(--es-text);margin:10px 0 12px;}
#es-app[data-suite="true"] .suite-result-hero .es-big-score small {font-size:.45em;margin-left:3px;letter-spacing:0;}
#es-app[data-suite="true"] .suite-result-hero p {font:12px/1.8 system-ui;color:var(--es-muted);}
#es-app[data-suite="true"] .suite-result-metrics {display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px 18px;align-content:center;border-left:1px solid var(--es-line);padding-left:28px;}
#es-app[data-suite="true"] .suite-result-metrics div {display:flex;flex-direction:column;gap:6px;font-size:12px;color:var(--es-muted);}
#es-app[data-suite="true"] .suite-result-metrics b {font:600 21px/1.2 system-ui;color:var(--es-text);}
#es-app[data-suite="true"] .suite-session-safety {display:flex;align-items:flex-start;gap:12px;margin:18px 0;padding:14px 16px;border:1px solid var(--es-line);border-left:3px solid var(--es-accent);border-radius:10px;background:var(--es-soft);color:var(--es-text);font:12px/1.65 system-ui;}
#es-app[data-suite="true"] .suite-session-safety svg {width:18px;height:18px;flex:0 0 18px;margin-top:2px;}
#es-app[data-suite="true"] .suite-session-safety strong {display:block;font-size:13px;}
#es-app[data-suite="true"] .suite-session-safety p {margin:4px 0 0;color:var(--es-muted);}
#es-app[data-suite="true"] .suite-session-safety[data-kind="learning"] {border-left-width:5px;outline:1px solid var(--es-line);}
#es-app[data-suite="true"] .es-result-diagnostics {background:none;border:0;padding:0 0 20px;margin:0;color:var(--es-text);}
#es-app[data-suite="true"] .es-result-diagnostics h3, #es-app[data-suite="true"] .suite-result-breakdown h3, #es-app[data-suite="true"] .suite-result-title h3 {font:600 16px/1.4 system-ui;margin:0 0 8px;}
#es-app[data-suite="true"] .es-result-diagnostics p {font:13px/1.7 system-ui;color:var(--es-muted);margin:0;}
#es-app[data-suite="true"] .suite-result-breakdown {margin:4px 0 22px;}
#es-app[data-suite="true"] .suite-result-deck {display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:18px;padding:12px 0;border-bottom:1px solid var(--es-line);font:13px/1.6 system-ui;}
#es-app[data-suite="true"] .suite-result-deck span {overflow-wrap:anywhere;}
#es-app[data-suite="true"] .suite-result-deck small {color:var(--es-muted);}
#es-app[data-suite="true"] .suite-result-title {display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap;}
#es-app[data-suite="true"] .suite-result-title label {display:flex;gap:8px;align-items:center;font:12px/1.4 system-ui;color:var(--es-muted);}
#es-app[data-suite="true"] .suite-result-title select {width:auto;max-width:210px;min-height:36px;}
#es-app[data-suite="true"] .suite-result-detail-note {font-size:12px;color:var(--es-muted);margin:0 0 14px;}
#es-app[data-suite="true"] .suite-result-table {border:1px solid var(--es-line);border-radius:12px;overflow:hidden;font:12px/1.5 system-ui;}
#es-app[data-suite="true"] .suite-result-table [role="row"] {display:grid;grid-template-columns:75px 1.1fr 1.3fr 1.2fr;gap:14px;padding:12px 15px;border-bottom:1px solid var(--es-line);}
#es-app[data-suite="true"] .suite-result-table [role="row"]:last-child {border:0;}
#es-app[data-suite="true"] .suite-result-table small {display:block;color:var(--es-muted);font-size:10px;margin-top:3px;}
#es-app[data-suite="true"] .suite-result-table [role="cell"] {min-width:0;overflow-wrap:anywhere;}
#es-app[data-suite="true"] .suite-result-table-head {background:var(--es-soft);font-weight:600;color:var(--es-muted);}
#es-app[data-suite="true"] .suite-result-pagination {display:flex;gap:12px;flex-wrap:wrap;justify-content:space-between;align-items:center;margin-top:12px;font:12px/1.6 system-ui;color:var(--es-muted);}
#es-app[data-suite="true"] .suite-result-pagination>div {display:flex;gap:6px;}
#es-app[data-suite="true"] .suite-session-empty {padding:24px;border:1px dashed var(--es-line);border-radius:12px;color:var(--es-muted);font:13px/1.7 system-ui;}
#es-app[data-suite="true"] .suite-result-method {margin-top:24px;padding:14px 16px;background:var(--es-soft);border-radius:10px;font:12px/1.75 system-ui;color:var(--es-muted);}
#es-app[data-suite="true"] .suite-result-method summary {cursor:pointer;font-weight:600;color:var(--es-text);}
#es-app[data-suite="true"] .suite-result-method p {margin:12px 0 0;}
#es-app[data-suite="true"] .suite-pip-intro {display:flex;gap:20px;align-items:center;}
#es-app[data-suite="true"] .suite-pip-avatar {flex:0 0 100px;background:linear-gradient(180deg,var(--es-soft),var(--es-surface));border:1px solid var(--es-line);border-radius:20px;padding:18px;}
#es-app[data-suite="true"] .suite-pip-avatar img {width:64px;height:80px;object-fit:contain;}
#es-app[data-suite="true"] .suite-pip-intro h3 {font:500 25px/1.3 var(--world-font,system-ui);margin:7px 0 10px;color:var(--es-text);}
#es-app[data-suite="true"] .suite-pip-intro p {font:13px/1.7 system-ui;color:var(--es-muted);}
#es-app[data-suite="true"] .suite-pip-count {margin-top:24px;}
#es-app[data-suite="true"] .suite-pip-count input {max-width:180px;}
#es-app[data-suite="true"] .suite-pip-choice {padding:18px;border:1px solid var(--es-line);border-radius:12px;align-items:flex-start;}
#es-app[data-suite="true"] .suite-pip-choice input {flex-shrink:0;margin-top:3px;}
#es-app[data-suite="true"] .suite-resume-card {display:flex;gap:18px;align-items:center;padding:20px 22px;border:1px solid var(--es-line);border-radius:var(--world-radius,16px);background:var(--es-soft);margin:0 0 22px;}
#es-app[data-suite="true"] .suite-resume-card>div:nth-child(2) {flex:1;min-width:0;}
#es-app[data-suite="true"] .suite-resume-card h3 {font:600 16px/1.5 system-ui;margin:6px 0;color:var(--es-text);}
#es-app[data-suite="true"] .suite-resume-card small {display:block;font:11px/1.6 system-ui;color:var(--es-muted);margin-top:8px;}
#es-app[data-suite="true"] .suite-resume-symbol {width:38px;height:38px;display:grid;place-items:center;flex-shrink:0;background:var(--es-surface);border-radius:10px;}
#es-app[data-suite="true"] .suite-resume-symbol svg {width:20px;height:20px;}
#es-app[data-suite="true"] .es-history-row {gap:18px;padding:16px;border:1px solid var(--es-line);border-radius:12px;background:var(--es-surface);margin-top:8px;}
#es-app[data-suite="true"] .es-history-row>div {flex:1;min-width:0;font:12px/1.6 system-ui;}
#es-app[data-suite="true"] .es-history-row p {margin:3px 0 0;}
#es-app[data-suite="true"] .es-history-row .es-score {font:500 24px/1.2 var(--world-font,system-ui);color:var(--es-accent);}
#es-app[data-suite="true"] .es-companion-panel .pip-card {border-radius:var(--world-radius,20px) var(--world-radius,20px) 0 0;}
#es-app[data-suite="true"] .es-modal :focus-visible {outline:2px solid var(--es-accent);outline-offset:3px;}
@media(max-width:650px){
 #es-app[data-suite="true"] .es-modal,#es-app[data-suite="true"] .es-modal[data-view="results"] {width:calc(100vw - 16px);max-width:calc(100vw - 16px);max-height:calc(100dvh - 16px);border-radius:14px;}
 #es-app[data-suite="true"] .es-modal-inner {max-height:calc(100dvh - 18px);}
 #es-app[data-suite="true"] .suite-modal-heading {padding:16px;gap:8px;}
 #es-app[data-suite="true"] .suite-modal-scroll {padding:16px;}
 #es-app[data-suite="true"] .es-modal .es-modal-actions {padding:12px;gap:6px;}
 #es-app[data-suite="true"] .es-modal-actions button {min-height:36px;font-size:12px;padding:8px 10px;flex:1 1 auto;}
 #es-app[data-suite="true"] .suite-result-hero {grid-template-columns:1fr;padding:18px;gap:20px;}
 #es-app[data-suite="true"] .suite-result-metrics {border-left:0;border-top:1px solid var(--es-line);padding-left:0;padding-top:18px;}
 #es-app[data-suite="true"] .suite-result-deck {gap:10px;grid-template-columns:minmax(0,1fr) auto;}
 #es-app[data-suite="true"] .suite-result-deck small {grid-column:1/-1;}
 #es-app[data-suite="true"] .suite-result-table [role="row"] {grid-template-columns:42px .95fr 1.1fr;gap:8px;padding:10px;}
 #es-app[data-suite="true"] .suite-result-table [role="row"]>:last-child {grid-column:2/-1;}
 #es-app[data-suite="true"] .suite-result-table-head>:last-child {display:none;}
 #es-app[data-suite="true"] .suite-pip-avatar {flex-basis:72px;padding:9px;}
 #es-app[data-suite="true"] .suite-pip-avatar img {width:52px;height:70px;}
 #es-app[data-suite="true"] .suite-pip-intro {gap:12px;align-items:flex-start;}
 #es-app[data-suite="true"] .suite-pip-intro h3 {font-size:21px;}
 #es-app[data-suite="true"] .suite-resume-card {flex-wrap:wrap;padding:16px;gap:12px;}
 #es-app[data-suite="true"] .suite-resume-card>.es-flex {margin-left:auto;}
}
@media(forced-colors:active){#es-app[data-suite="true"] .suite-session-safety,#es-app[data-suite="true"] .es-modal {border:1px solid CanvasText;}}
@media(prefers-reduced-motion:reduce){#es-app[data-suite="true"] .es-modal *{transition:none!important;animation:none!important;}}

#es-app[data-suite="true"] .suite-modal-alerts {flex-shrink:0;padding:0 18px;}
#es-app[data-suite="true"] .suite-modal-alerts .es-toast {position:static;transform:none;width:auto;max-width:100%;margin:12px 0 0;box-sizing:border-box;}

web/shared.css:
/* Atelier Shared Home 0.7.1. Applied ONLY to the DeckBrowser document.
   Presentation adapters for known Onigiri surfaces; game canvases, SVG artwork,
   images, widget scripts, hidden state, and stored Onigiri settings are untouched. */
html[data-atelier-shared="true"],
html[data-atelier-shared="true"] body,
html[data-atelier-shared="true"] .modern-main-menu {
  --canvas:var(--ats-bg)!important; --canvas-inset:var(--ats-panel)!important;
  --canvas-elevated:var(--ats-raised)!important; --canvas-overlay:var(--ats-panel)!important;
  --fg:var(--ats-text)!important; --fg-default:var(--ats-text)!important;
  --fg-subtle:var(--ats-muted)!important; --fg-muted:var(--ats-muted)!important;
  --border:var(--ats-line)!important; --border-subtle:var(--ats-line-soft)!important;
  --link:var(--ats-accent)!important; --accent-color:var(--ats-accent)!important;
  --icon-color:var(--ats-accent)!important; --button-bg:var(--ats-raised)!important;
  --font-main: -apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif!important;
  --font-small-title:var(--font-main)!important; --font-big-title:var(--font-main)!important;
  --font-deck:var(--font-main)!important; --font-body:var(--font-main)!important;
  --font-stats:var(--font-main)!important;
  color-scheme:var(--ats-scheme)!important;
  background:var(--ats-bg)!important; color:var(--ats-text)!important;
  font-family:var(--font-main)!important;
}
html[data-atelier-shared="true"] body { text-shadow:none!important; }
html[data-atelier-shared="true"] .modern-main-menu { box-sizing:border-box!important; gap:24px!important; }
html[data-atelier-shared="true"] .modern-main-menu .main-content {
  min-width:0!important; background:transparent!important; color:var(--ats-text)!important;
  box-sizing:border-box!important; padding-bottom:28px!important;
}
html[data-atelier-shared="true"] .modern-main-menu .injected-stats-block {min-width:0!important;max-width:100%!important;width:100%!important;}
html[data-atelier-shared="true"] .modern-main-menu .sidebar-left {
  background:var(--ats-side)!important; color:var(--ats-text)!important;
  border:1px solid var(--ats-line)!important; border-radius:20px!important;
  box-shadow:0 8px 32px #0000000b!important; backdrop-filter:none!important;
}
html[data-atelier-shared="true"] .modern-main-menu:not(.onigiri-sidebar-center):not(.onigiri-cycle-stacked) > .sidebar-left:not(.collapsed):not(.sidebar-collapsed) {
  max-width:min(420px,40vw)!important;
}
html[data-atelier-shared="true"] .modern-main-menu .sidebar-expanded-content { background:transparent!important;min-height:0!important; }
html[data-atelier-shared="true"] .modern-main-menu .sidebar-left :is(h1,h2,h3,.welcome-text,.welcome-message,.profile-name,.opro-name) {
  color:var(--ats-text)!important;font-family:var(--font-main)!important;text-shadow:none!important;
}
html[data-atelier-shared="true"] .modern-main-menu .sidebar-left :is(.menu-item,.add-button-dashed,.menu-group summary) {
  color:var(--ats-muted)!important; font-family:var(--font-main)!important; font-size:14px!important;
  line-height:1.5!important; border-radius:10px!important;
}
html[data-atelier-shared="true"] .modern-main-menu .sidebar-left :is(.menu-item,.add-button-dashed,.menu-group summary):hover {background:var(--ats-hover)!important;color:var(--ats-text)!important;}
html[data-atelier-shared="true"] .modern-main-menu .sidebar-left .add-button-dashed,
html[data-atelier-shared="true"] .modern-main-menu .sidebar-left .action-add {border-color:var(--ats-line)!important;}
html[data-atelier-shared="true"] .modern-main-menu .sidebar-left .profile-bar {background:var(--ats-raised)!important;border:1px solid var(--ats-line)!important;border-radius:16px!important;}
html[data-atelier-shared="true"] .modern-main-menu .profile-bg-layer {opacity:.12!important;}
html[data-atelier-shared="true"] .modern-main-menu :is(.rl-chip-level,.restaurant-level-chip) {color:var(--ats-text)!important;font-family:var(--font-main)!important;}
html[data-atelier-shared="true"] .modern-main-menu .deck-table {width:100%!important;table-layout:fixed!important;border-spacing:0 3px!important;}
html[data-atelier-shared="true"] .modern-main-menu .decktd {min-width:0!important;gap:4px!important;}
html[data-atelier-shared="true"] .modern-main-menu a.deck {
  font:500 13px/1.5 var(--font-main)!important; color:var(--ats-text)!important;
  min-width:0!important;overflow:hidden!important;overflow-wrap:anywhere!important;
  text-overflow:ellipsis!important;white-space:normal!important; padding:8px 5px!important;
}
html[data-atelier-shared="true"] .modern-main-menu tr.deck:hover {background:var(--ats-hover)!important;}
html[data-atelier-shared="true"] .modern-main-menu tr:is(.selected,.current,.deck-selected) {background:var(--ats-accent-soft)!important;}
html[data-atelier-shared="true"] .modern-main-menu :is(.collapse,.deck-collapse,.decktd .collapse) {color:var(--ats-muted)!important;}
html[data-atelier-shared="true"] .modern-main-menu :is(.onigiri-widget-title,.main-content h1) {
  color:var(--ats-text)!important;font-family:var(--font-main)!important;
  font-size:clamp(22px,2vw,30px)!important;line-height:1.3!important;letter-spacing:-.7px!important;
}
html[data-atelier-shared="true"] .modern-main-menu :is(.stat-card,.onigiri-restaurant-level-widget,.onigiri-favorites-widget,#onigiri-heatmap-container,.prep-station-widget,.hashi-notes-widget,.onigimon-widget,.hex-land-widget) {
  background:var(--ats-panel)!important;color:var(--ats-text)!important;
  border:1px solid var(--ats-line)!important;border-radius:18px!important;
  box-shadow:0 4px 18px #00000008!important;
}
html[data-atelier-shared="true"] .modern-main-menu :is(.stat-card h3,.onigiri-widget-head h3,.restaurant-info h3,.restaurant-info .level-label) {
  color:var(--ats-muted)!important;font:600 12px/1.45 var(--font-main)!important;
  letter-spacing:.65px!important;text-transform:uppercase!important;
}
html[data-atelier-shared="true"] .modern-main-menu :is(.stat-value,.restaurant-level,.restaurant-level-number,.level-number,.level-value) {
  color:var(--ats-text)!important;font-family:var(--font-main)!important;
  line-height:1.25!important;letter-spacing:-.75px!important;font-variant-numeric:tabular-nums;
}
html[data-atelier-shared="true"] .modern-main-menu .stat-value {font-size:clamp(22px,2.8vw,34px)!important;}
html[data-atelier-shared="true"] .modern-main-menu :is(.stat-unit,.restaurant-info,.restaurant-info p,.restaurant-info span,.favorites-placeholder,.favorites-list a) {
  font-family:var(--font-main)!important;color:var(--ats-muted)!important;text-shadow:none!important;
}
html[data-atelier-shared="true"] .modern-main-menu :is(.star-rating,.stat-icon-chip) {color:var(--ats-accent)!important;}
html[data-atelier-shared="true"] .modern-main-menu :is(.favorites-list a:hover,.onigiri-favorite-item:hover) {background:var(--ats-hover)!important;color:var(--ats-text)!important;}
html[data-atelier-shared="true"] .modern-main-menu :is(#deck-list-container,.main-content,.sidebar-left) {scrollbar-color:var(--ats-line) transparent;scrollbar-width:thin;}
html[data-atelier-shared="true"] .modern-main-menu :is(input,textarea,select):not([type="color"]):not([type="checkbox"]):not([type="range"]) {
  color:var(--ats-text);border-color:var(--ats-line);background-color:var(--ats-panel);
}
/* All original widget nodes stay where their owning add-on put them.
   Unknown content keeps its typography/artwork. Only its outer clipping is fixed. */
html[data-atelier-shared="true"] .modern-main-menu .external-widget-container {
  min-width:0!important;max-width:100%!important;box-sizing:border-box!important;
  scrollbar-width:thin;scrollbar-color:var(--ats-line) transparent;
}
html[data-atelier-shared="true"] .modern-main-menu .unified-grid {max-width:100%!important;}
html[data-atelier-shared="true"] .modern-main-menu .unified-grid[data-atelier-grid-columns] {
  grid-template-columns:repeat(var(--ats-grid-columns),minmax(0,1fr))!important;
}
html[data-atelier-shared="true"] .modern-main-menu .unified-grid[data-atelier-grid-compact="true"] {
  grid-template-rows:none!important;grid-auto-rows:minmax(140px,auto)!important;align-items:stretch!important;
}
html[data-atelier-shared="true"] .modern-main-menu .unified-grid[data-atelier-grid-compact="true"] > :is(.onigiri-widget-container,.external-widget-container) {
  grid-row:auto!important;grid-column:span var(--ats-widget-span,1)!important;
  min-width:0!important;min-height:0!important;height:auto!important;
}
html[data-atelier-shared="true"] .modern-main-menu .unified-grid[data-atelier-grid-compact="true"] > [data-atelier-widget-title] {grid-column:1 / -1!important;}
/* Sprout is a real responsive widget, not a sliver in a one-column tile. */
html[data-atelier-home] .external-widget-container[data-atelier-sprout-wrap] {
  grid-column:1 / -1!important;grid-row:auto!important;align-self:start!important;
  width:100%!important;max-width:100%!important;min-width:0!important;
  height:auto!important;min-height:0!important;max-height:none!important;
  overflow:visible!important;contain:none!important;box-sizing:border-box!important;
}
html[data-atelier-home] .external-widget-container[data-atelier-sprout-wrap="empty"] {display:none!important;}
html[data-atelier-home] #es-countdowns {
  width:100%!important;max-width:100%!important;min-width:0!important;box-sizing:border-box!important;
  margin:0!important;padding:0!important;display:grid!important;
  grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr))!important;
  align-items:stretch!important;justify-content:stretch!important;gap:12px!important;
  font:14px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif!important;
  text-align:left!important;container-type:inline-size;
}
html[data-atelier-home] #es-countdowns .es-chip {
  display:grid!important;grid-template-columns:36px minmax(0,1fr) auto 16px!important;
  align-items:center!important;gap:12px!important;width:100%!important;
  max-width:100%!important;min-width:0!important;height:auto!important;min-height:78px!important;
  padding:14px!important;border-radius:16px!important;overflow:visible!important;
  font:inherit!important;line-height:1.4!important;text-shadow:none!important;
  transform:none!important;box-shadow:none!important;letter-spacing:normal!important;
}
html[data-atelier-home] #es-countdowns .es-chip-copy {min-width:0!important;}
html[data-atelier-home] #es-countdowns .es-chip-title {font:600 14px/1.4 -apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif!important;white-space:normal!important;overflow-wrap:anywhere!important;}
html[data-atelier-home] #es-countdowns .es-chip-sub {font-size:11px!important;white-space:normal!important;overflow-wrap:anywhere!important;opacity:1!important;}
html[data-atelier-home] #es-countdowns .es-time {font-size:13px!important;margin:0!important;padding:8px!important;}
html[data-atelier-home] #es-countdowns .es-chip-empty .es-plus {grid-column:3!important;}
html[data-atelier-home] #es-countdowns .es-mark {background:var(--es-tint)!important;}
html[data-atelier-home][data-atelier-match-sprout="true"] #es-countdowns {
  --es-accent:var(--ats-accent)!important;--es-tint:var(--ats-panel)!important;
  --es-chip-line:var(--ats-line)!important;color:var(--ats-text)!important;
}
html[data-atelier-home][data-atelier-match-sprout="true"] #es-countdowns .es-chip {
  background:var(--ats-panel)!important;color:var(--ats-text)!important;border:1px solid var(--ats-line)!important;
}
html[data-atelier-home][data-atelier-match-sprout="true"] #es-countdowns .es-chip:hover {background:var(--ats-raised)!important;border-color:var(--ats-accent)!important;}
html[data-atelier-home][data-atelier-match-sprout="true"] #es-countdowns .es-chip-sub {color:var(--ats-muted)!important;}
html[data-atelier-home][data-atelier-match-sprout="true"] #es-countdowns .es-time {background:var(--ats-accent-soft)!important;color:var(--ats-accent)!important;}
html[data-atelier-home] #es-countdowns .es-chip:focus-visible {outline:2px solid var(--es-accent)!important;outline-offset:3px!important;}
@container (max-width:300px) {
  html[data-atelier-home] #es-countdowns .es-chip {grid-template-columns:32px minmax(0,1fr)!important;gap:8px!important;}
  html[data-atelier-home] #es-countdowns .es-time {grid-column:2!important;justify-self:start!important;}
  html[data-atelier-home] #es-countdowns .es-chip-arrow {display:none!important;}
}
@media(max-width:700px) {
  html[data-atelier-shared="true"] .modern-main-menu {flex-direction:column!important;height:auto!important;min-height:100vh!important;padding:12px!important;gap:16px!important;}
  html[data-atelier-shared="true"] .modern-main-menu > .sidebar-left:not(.collapsed):not(.sidebar-collapsed) {width:100%!important;max-width:none!important;min-width:0!important;max-height:320px!important;}
  html[data-atelier-shared="true"] .modern-main-menu .main-content {width:100%!important;overflow:visible!important;margin:0!important;padding:0 0 24px!important;}
  html[data-atelier-shared="true"] body {overflow-y:auto!important;overflow-x:hidden!important;}
}
@media(prefers-reduced-motion:reduce) {
  html[data-atelier-home] #es-countdowns .es-chip,html[data-atelier-home] #es-countdowns .es-chip-arrow {transition:none!important;transform:none!important;}
}
html[data-atelier-home][data-atelier-shared] .modern-main-menu .unified-grid > .external-widget-container[data-atelier-sprout-wrap] {
  grid-column:1 / -1!important;grid-row:auto!important;height:auto!important;min-height:0!important;max-height:none!important;overflow:visible!important;
}
/* Small native controls remain compact, but not olive on a different theme. */
html[data-atelier-shared="true"] .modern-main-menu .sidebar-left :is(.sidebar-top-buttons button,.sidebar-top-actions button,.deck-header-btn,.deck-focus-btn) {
  background-color:var(--ats-raised)!important;color:var(--ats-accent)!important;border-color:var(--ats-line)!important;
}
html[data-atelier-shared="true"] .modern-main-menu .sidebar-left :is(.sidebar-top-buttons button,.sidebar-top-actions button,.deck-header-btn,.deck-focus-btn):hover {
  background-color:var(--ats-hover)!important;
}
html[data-atelier-shared="true"] .modern-main-menu :is(.rl-chip-level,.restaurant-level-chip) {background-color:var(--ats-accent-soft)!important;color:var(--ats-accent)!important;}
html[data-atelier-shared="true"] .modern-main-menu .sidebar-left :is(.folder-icon,.sidebar-menu a) {color:var(--ats-muted)!important;font-family:var(--font-main)!important;}
html[data-atelier-shared="true"] .modern-main-menu :is(.hashi-notes-widget h3,.onigiri-favorites-widget h3) {color:var(--ats-muted)!important;font:600 12px/1.5 var(--font-main)!important;letter-spacing:.65px!important;}

/* Preserve themed game art when Onigiri intentionally expands its building. */
html[data-atelier-shared="true"] .modern-main-menu .onigiri-restaurant-level-widget.expanded-view {background:var(--theme-bg,var(--ats-panel))!important;}
/* Atelier owns the interface. Onigiri's widget DOM/game remains original,
   but its redundant folder navigation does not compete with the organizer. */
html[data-atelier-owner="atelier"][data-atelier-shared="true"] body,
html[data-atelier-owner="atelier"][data-atelier-shared="true"] .modern-main-menu{background:var(--ats-bg)!important;color:var(--ats-text)!important;}
html[data-atelier-owner="atelier"] .modern-main-menu>.sidebar-left,
html[data-atelier-owner="atelier"] .modern-main-menu>.resize-handle,
html[data-atelier-owner="atelier"] #onigiri-sidebar-edge-pill{display:none!important;}
html[data-atelier-owner="atelier"] .modern-main-menu>.main-content{width:100%!important;max-width:1500px!important;margin:0 auto!important;padding:24px 32px 40px!important;overflow:auto!important;}
html[data-atelier-owner="atelier"] .modern-main-menu{gap:0!important;}
html[data-atelier-owner="atelier"] .modern-main-menu .onigiri-widget-title{font-size:22px!important;}
html[data-atelier-owner="atelier"] .modern-main-menu .stat-card{background:linear-gradient(140deg,var(--ats-panel),var(--ats-hero-end))!important;border-radius:20px!important;}
html[data-atelier-owner="atelier"] .modern-main-menu :is(.rl-chip-level,.restaurant-level-chip){background:var(--ats-accent-soft)!important;color:var(--ats-accent-strong)!important;}
html[data-atelier-home][data-atelier-match-sprout="true"] #es-countdowns .es-chip{background:linear-gradient(120deg,var(--ats-panel),var(--ats-hero-end))!important;border-radius:17px!important;min-height:66px!important;}
html[data-atelier-home][data-atelier-match-sprout="true"] #es-countdowns .es-time{background:var(--ats-accent-soft)!important;color:var(--ats-accent-strong)!important;}
@media(max-width:700px){html[data-atelier-owner="atelier"] .modern-main-menu>.main-content{padding:12px!important;}}

/* Balanced widget layout only when Atelier owns the page. Original nodes stay in place. */
html[data-atelier-owner="atelier"] .modern-main-menu>.main-content{max-width:1360px!important;padding:22px 28px 40px!important;}
html[data-atelier-owner="atelier"] .modern-main-menu .main-content>h1,html[data-atelier-owner="atelier"] .onigiri-widget-title{margin:18px 0 14px!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced]{grid-template-columns:repeat(var(--ats-grid-columns),minmax(0,1fr))!important;grid-auto-rows:minmax(150px,auto)!important;gap:16px!important;align-items:stretch!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced]>:is(.onigiri-widget-container,.external-widget-container){grid-column:span 1!important;grid-row:auto!important;height:auto!important;min-height:0!important;max-height:none!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced]>[data-atelier-widget-title],html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced]>.external-widget-container{grid-column:1 / -1!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced="4"]>[data-atelier-building]{grid-column:span 2!important;grid-row:span 2!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced="2"]>[data-atelier-building]{grid-column:1 / -1!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced] .stat-card{min-height:150px!important;height:100%!important;padding:22px!important;box-sizing:border-box!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced] .onigiri-restaurant-level-widget:not(.expanded-view){min-height:280px!important;max-height:none!important;height:100%!important;box-sizing:border-box!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced] .onigiri-restaurant-level-widget:not(.expanded-view) img{max-height:300px;object-fit:contain;}
@media(max-width:700px){html[data-atelier-owner="atelier"] .modern-main-menu>.main-content{padding:14px!important;}html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced] .stat-card{padding:18px!important;min-height:130px!important;}}

/* Compact, content-first rewards room. Provider containers stay live and intact. */
html[data-atelier-owner="atelier"] .modern-main-menu .injected-stats-block{box-sizing:border-box!important;min-width:0!important;max-width:100%!important;align-items:stretch!important;gap:0!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced]{grid-auto-rows:minmax(114px,auto)!important;gap:14px!important;grid-auto-flow:row dense!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced]>[data-atelier-building]{order:0!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced]>[data-atelier-metric]{order:1!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced]>[data-atelier-widget-title]{order:-1!important;min-height:0!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced]>.external-widget-container{order:5!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced] .stat-card{min-height:114px!important;padding:16px!important;border-radius:16px!important;gap:10px!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced] .stat-card .stat-value{font-size:26px!important;line-height:1.2!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced] .onigiri-restaurant-level-widget:not(.expanded-view){display:grid!important;grid-template-columns:minmax(100px,42%) minmax(0,1fr)!important;align-items:center!important;gap:18px!important;padding:20px!important;min-height:242px!important;border-radius:18px!important;overflow:visible!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced] .onigiri-restaurant-level-widget:not(.expanded-view) .restaurant-image-container{width:100%!important;max-width:200px!important;min-width:0!important;height:auto!important;max-height:185px!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced] .onigiri-restaurant-level-widget:not(.expanded-view) img{width:100%!important;height:auto!important;max-height:185px!important;object-fit:contain!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced] .onigiri-restaurant-level-widget:not(.expanded-view) .restaurant-info{width:auto!important;min-width:0!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced] .onigiri-restaurant-level-widget:not(.expanded-view) :is(.level-number,.restaurant-level-number,.level-value){font-size:36px!important;}
html[data-atelier-owner="atelier"] .modern-main-menu .injected-stats-block>h1{font-size:22px!important;margin:8px 0 14px!important;line-height:1.25!important;}
@media(max-width:600px){html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced] .onigiri-restaurant-level-widget:not(.expanded-view){padding:16px!important;gap:12px!important;min-height:215px!important;}}
/* Beat the legacy responsive grid rule, not the widget's own interactive content. */
html[data-atelier-owner="atelier"] .modern-main-menu .unified-grid[data-atelier-balanced="4"][data-atelier-grid-compact]>.onigiri-widget-container[data-atelier-building]{grid-column:span 2!important;grid-row:span 2!important;align-self:stretch!important;}
html[data-atelier-owner="atelier"] .modern-main-menu .unified-grid[data-atelier-balanced="2"][data-atelier-grid-compact]>.onigiri-widget-container[data-atelier-building],html[data-atelier-owner="atelier"] .modern-main-menu .unified-grid[data-atelier-balanced="1"][data-atelier-grid-compact]>.onigiri-widget-container[data-atelier-building]{grid-column:1/-1!important;grid-row:auto!important;}
html[data-atelier-owner="atelier"] .modern-main-menu .unified-grid[data-atelier-balanced][data-atelier-grid-compact]>.external-widget-container{grid-column:1/-1!important;grid-row:auto!important;}
/* Let title/utility rows size to their content; only the metrics have a minimum. */
html[data-atelier-owner="atelier"] .modern-main-menu .unified-grid[data-atelier-balanced][data-atelier-grid-compact]{grid-auto-rows:minmax(0,auto)!important;}

web/studio-home.css:
/* Shared control rhythm for the accepted home. Library/navigation logic unchanged.
   Shadow-scoped: no Onigiri, card or external-window selectors. */
:host {--studio-control:40px;}
.unified-topbar .top-actions {align-items:center;gap:8px;}
.unified-topbar [data-command] {min-height:var(--studio-control);border-radius:10px;padding:9px 13px;display:inline-flex;align-items:center;gap:8px;font-size:13px;line-height:1.35;}
.unified-topbar .search {min-height:40px;border-radius:10px;}
.unified-topbar .icon-button {width:38px;height:38px;border-radius:10px;}
.unified-topbar :is(button,input) {box-shadow:none;}
:host([data-motion="false"]) .unified-topbar * {transition:none!important;}
@media(max-width:740px) {.unified-topbar [data-command]{font-size:12px;padding:8px 10px;min-height:38px;gap:6px;}}
@media(max-width:480px) {.unified-topbar [data-command]{font-size:11px;padding:8px 7px;}}
@media(prefers-reduced-motion:reduce){.unified-topbar *{transition:none!important;transform:none!important;}}

web/studio-shell.css:
/* Atelier Studio shell · rc3
   Layout for the bundled planner only. The assessment engine, card Previewer,
   practice runner and original standalone stylesheet are deliberately untouched.
   Header rows occupy real layout space; only the content/rail scroll. */
html.es-host:has(#es-app[data-suite="true"]),
html.es-host:has(#es-app[data-suite="true"]) body {height:100%;margin:0;padding:0;overflow:hidden;}
#es-app[data-suite="true"] {
  --studio-control:40px; --studio-radius:18px; --studio-gutter:clamp(20px,2.4vw,34px);
  height:100vh;height:100dvh;min-height:0;max-width:100%;display:grid;
  grid-template-rows:auto minmax(0,1fr);overflow:hidden;isolation:isolate;
  font:14px/1.55 "Segoe UI",-apple-system,BlinkMacSystemFont,Arial,sans-serif;
}
#es-app[data-suite="true"] :is(button,input,select,textarea){box-sizing:border-box;}
#es-app[data-suite="true"] button {touch-action:manipulation;}
#es-app[data-suite="true"] button:active {transform:none;}
html #es-app[data-suite="true"] .es-app-header {
  display:grid!important;grid-template-columns:minmax(180px,1fr) auto auto;
  grid-template-areas:"brand tools world" "nav nav nav";align-items:center;
  position:relative!important;inset:auto!important;height:auto!important;min-height:0!important;
  max-height:none!important;padding:12px 24px 0!important;gap:10px 18px!important;
  background:var(--es-surface);border-bottom:1px solid var(--es-line);z-index:8;
  width:100%;flex-shrink:0;box-shadow:none;
}
#es-app[data-suite="true"] .es-brand {grid-area:brand;min-width:0;gap:10px;font-size:23px;align-items:center;}
#es-app[data-suite="true"] .es-brand::after {display:none!important;}
#es-app[data-suite="true"] .es-brand-mark {width:32px;height:34px;flex:0 0 32px;background:transparent;border:0;box-shadow:none;}
#es-app[data-suite="true"] .es-brand-mark img {width:32px;height:34px;object-fit:contain;}
#es-app[data-suite="true"] .suite-brand-copy {display:flex;align-items:baseline;gap:14px;min-width:0;}
#es-app[data-suite="true"] .suite-brand-copy>strong {font-size:23px;letter-spacing:-1px;line-height:1.2;}
#es-app[data-suite="true"] .es-header-note {display:block!important;font:12px/1.4 "Segoe UI",system-ui,sans-serif;letter-spacing:.05px;white-space:nowrap;padding:0;margin:0;border:0;color:var(--es-muted);}
#es-app[data-suite="true"] .suite-tool-links {grid-area:tools;display:flex;align-items:center;gap:6px;flex-wrap:nowrap;margin:0;}
#es-app[data-suite="true"] .suite-tool-links button {
  min-height:var(--studio-control);font:500 13px/1.35 "Segoe UI",system-ui,sans-serif;
  padding:9px 13px;display:inline-flex;align-items:center;justify-content:center;gap:8px;
  white-space:nowrap;border-radius:10px;background:var(--es-surface);color:var(--es-text);border:1px solid var(--es-line);
}
#es-app[data-suite="true"] .suite-tool-links button:first-child {background:var(--es-soft);border-color:var(--es-line);color:var(--es-accent);}
#es-app[data-suite="true"] .suite-tool-links svg {width:17px;height:17px;}
html #es-app[data-suite="true"] .suite-world-switch {grid-area:world;display:flex;gap:8px;margin:0;order:0;font-size:11px;color:var(--es-muted);position:relative;width:auto;}
#es-app[data-suite="true"] .suite-world-switch select {width:136px;max-width:136px;min-height:40px;padding:8px 10px;font-size:13px;line-height:1.4;}
#es-app[data-suite="true"] .suite-world-error {position:absolute;top:calc(100% + 8px);right:0;min-width:220px;max-width:300px;padding:12px;background:var(--es-surface);border:1px solid var(--es-danger);border-radius:10px;color:var(--es-text);z-index:12;box-shadow:0 8px 24px #0003;}
html #es-app[data-suite="true"] .es-top-nav {
  grid-area:nav;min-width:0;display:flex;flex-wrap:nowrap!important;align-items:stretch;
  gap:6px;background:transparent;border:0;border-top:1px solid var(--es-line);
  border-radius:0;padding:6px 0;box-shadow:none;width:100%;
}
#es-app[data-suite="true"] .es-top-nav button {
  display:inline-flex;gap:8px;align-items:center;justify-content:center;min-height:38px;
  font-size:13px;padding:8px 15px;line-height:1.3;white-space:nowrap;
  border-radius:9px;background:transparent;border:1px solid transparent;
}
#es-app[data-suite="true"] .es-top-nav button[aria-current="page"] {background:var(--es-soft);color:var(--es-accent);}
#es-app[data-suite="true"] .es-top-nav button svg {width:17px;height:17px;display:block;}
#es-app[data-suite="true"] .es-top-nav .suite-home-link {margin-left:auto;color:var(--es-muted);}
#es-app[data-suite="true"] .es-top-nav .suite-home-link svg {transform:rotate(180deg);}
#es-app[data-suite="true"] .es-layout {display:grid;grid-template-columns:208px minmax(0,1fr);min-height:0;height:100%;overflow:hidden;position:relative;}
#es-app[data-suite="true"] .suite-exams-toggle {display:none;}
html #es-app[data-suite="true"] .es-sidebar {padding:24px 14px 18px;gap:14px;width:auto;min-height:0;overflow-y:auto;overflow-x:hidden;overscroll-behavior:contain;scrollbar-gutter:stable;scrollbar-width:thin;scrollbar-color:var(--es-line) transparent;}
#es-app[data-suite="true"] .es-sidebar-label {padding:0 8px;}
#es-app[data-suite="true"] .es-sidebar-label .es-label {letter-spacing:1.3px;font-size:10px;}
#es-app[data-suite="true"] .es-exam-list {min-height:0;gap:8px;flex:none;}
#es-app[data-suite="true"] .es-exam-link {display:flex;gap:10px;align-items:flex-start;min-width:0;padding:12px 10px;min-height:62px;border-radius:12px;flex-shrink:0;}
#es-app[data-suite="true"] .es-exam-link>.es-exam-stamp {display:flex;flex-direction:column;justify-content:center;width:34px;min-width:34px;height:44px;border-radius:8px;font-size:18px;line-height:1.25;padding:5px;}
#es-app[data-suite="true"] .es-exam-link>.es-exam-stamp small {font-size:9px;}
#es-app[data-suite="true"] .es-exam-link-copy {display:block;min-width:0;flex:1;}
#es-app[data-suite="true"] .es-exam-link strong {font-size:12px;line-height:1.45;font-weight:600;overflow-wrap:anywhere;}
#es-app[data-suite="true"] .es-exam-link-copy>span {font-size:10px;line-height:1.5;}
#es-app[data-suite="true"] .es-sidebar-add {min-height:40px;flex-shrink:0;}
#es-app[data-suite="true"] .es-sidebar-footer {padding:22px 6px 0;line-height:1.6;font-size:10px;}
#es-app[data-suite="true"] .suite-companion-note {border:0;border-top:1px solid var(--es-line);border-radius:0;margin:0 0 20px;padding:16px 0 0;background:transparent;}
#es-app[data-suite="true"] .suite-companion-note summary {display:flex;align-items:center;gap:8px;font-size:12px;font-weight:600;line-height:1.4;list-style:none;color:var(--es-text);}
#es-app[data-suite="true"] .suite-companion-note summary::-webkit-details-marker {display:none;}
#es-app[data-suite="true"] .suite-companion-note summary::after {content:"+";margin-left:auto;color:var(--es-accent);font-size:17px;}
#es-app[data-suite="true"] .suite-companion-note[open] summary::after {content:"−";}
#es-app[data-suite="true"] .suite-companion-note summary small {display:block;color:var(--es-muted);font-weight:400;font-size:11px;}
#es-app[data-suite="true"] .suite-companion-note .es-sidebar-sprout {margin:0;flex:0 0 28px;width:28px;}
#es-app[data-suite="true"] .suite-companion-note img {width:28px;height:36px;object-fit:contain;}
#es-app[data-suite="true"] .suite-companion-note p {padding-top:10px;font-size:11px;color:var(--es-muted);}
#es-app[data-suite="true"] .suite-privacy-label {margin-bottom:5px;}
html #es-app[data-suite="true"] .es-main {
  min-height:0;min-width:0;width:100%;max-width:none;margin:0;padding:28px var(--studio-gutter) 32px;
  overflow-y:auto;overflow-x:hidden;overscroll-behavior:contain;scrollbar-gutter:stable;
  scrollbar-width:thin;scrollbar-color:var(--es-line) transparent;scroll-padding:20px;
}
#es-app[data-suite="true"] .es-main :focus-visible {scroll-margin-block:24px;}
#es-app[data-suite="true"][data-page="setup"] .es-main {display:flex;flex-direction:column;overflow:hidden;padding-top:24px;padding-bottom:0;}
#es-app[data-suite="true"] .suite-exam-editor {display:flex;flex-direction:column;flex:1;min-height:0;max-width:1320px;width:100%;margin:0 auto;border-radius:0;background:transparent;}
#es-app[data-suite="true"] .suite-form-heading {display:flex;justify-content:space-between;align-items:flex-start;gap:18px;flex:0 0 auto;padding:0 0 20px;}
#es-app[data-suite="true"] .suite-form-heading .es-label {font-size:10px;letter-spacing:1.4px;line-height:1.5;}
#es-app[data-suite="true"] .suite-form-heading h1 {font:500 clamp(26px,2.6vw,36px)/1.16 var(--world-font,"Segoe UI");letter-spacing:-.6px;margin-top:7px;color:var(--es-text);outline:0;}
#es-app[data-suite="true"] .suite-form-heading p {font-size:12px;line-height:1.65;margin-top:7px;max-width:76ch;color:var(--es-muted);}
#es-app[data-suite="true"] .suite-unsaved-state {font-size:10px;line-height:1.5;border:1px solid var(--es-line);border-radius:999px;padding:5px 9px;white-space:nowrap;margin-top:5px;color:var(--es-muted);background:var(--es-surface);}
