#es-app[data-suite="true"] .suite-schedule-safe {display:inline-flex;align-items:center;gap:7px;color:var(--es-accent);border:1px solid var(--es-line);border-radius:8px;background:var(--es-soft);font-size:11px;padding:8px 10px;}
