#es-app[data-suite="true"] :is(input,select,textarea) {color-scheme:inherit;}
#es-app[data-suite="true"] input[type="checkbox"] {accent-color:var(--es-accent);}
html #es-app[data-suite="true"] .suite-practice-grid>.es-practice-card {margin:0;}

web/world-finishes.css:
/* Final world finishes. Presentation only; no card geometry or external assets. */
:host([data-owner="atelier"][data-theme="obsidian"]),.mini-screen[data-theme="obsidian"],html[data-atelier-world-enabled="true"][data-atelier-world="obsidian"]{
 --finish-aperture:18px 5px 18px 5px;--finish-angle:120deg;--finish-alpha:0.035;--finish-pattern:linear-gradient(123deg,transparent 30%,var(--finish-line) 30.1%,transparent 30.4%,transparent 77%,var(--finish-line) 77.1%,transparent 77.4%);
}
:host([data-owner="atelier"][data-theme="glacier"]),.mini-screen[data-theme="glacier"],html[data-atelier-world-enabled="true"][data-atelier-world="glacier"]{
 --finish-aperture:6px 22px 6px 22px;--finish-angle:145deg;--finish-alpha:0.04;--finish-pattern:linear-gradient(155deg,transparent 55%,var(--finish-line) 55.1%,transparent 55.4%),linear-gradient(25deg,transparent 75%,var(--finish-line) 75.1%,transparent 75.4%);
}
:host([data-owner="atelier"][data-theme="rose"]),.mini-screen[data-theme="rose"],html[data-atelier-world-enabled="true"][data-atelier-world="rose"]{
 --finish-aperture:70px 70px 14px 14px;--finish-angle:110deg;--finish-alpha:0.025;--finish-pattern:radial-gradient(ellipse at 90% 130%,transparent 52%,var(--finish-line) 52.2%,transparent 52.5%,transparent 64%,var(--finish-line) 64.2%,transparent 64.5%);
}
:host([data-owner="atelier"][data-theme="bloom"]),.mini-screen[data-theme="bloom"],html[data-atelier-world-enabled="true"][data-atelier-world="bloom"]{
 --finish-aperture:32px 10px 32px 10px;--finish-angle:135deg;--finish-alpha:0.025;--finish-pattern:linear-gradient(90deg,transparent 49.8%,var(--finish-line) 50%,transparent 50.2%),linear-gradient(0deg,transparent 49.8%,var(--finish-line) 50%,transparent 50.2%);
}
:host([data-owner="atelier"][data-theme="linen"]),.mini-screen[data-theme="linen"],html[data-atelier-world-enabled="true"][data-atelier-world="linen"]{
 --finish-aperture:5px;--finish-angle:90deg;--finish-alpha:0.023;--finish-pattern:repeating-linear-gradient(90deg,transparent 0 3px,var(--finish-line) 3px 4px),repeating-linear-gradient(0deg,transparent 0 3px,var(--finish-line) 3px 4px);
}
:host([data-owner="atelier"][data-theme="matcha"]),.mini-screen[data-theme="matcha"],html[data-atelier-world-enabled="true"][data-atelier-world="matcha"]{
 --finish-aperture:8px 24px 8px 24px;--finish-angle:160deg;--finish-alpha:0.025;--finish-pattern:repeating-linear-gradient(90deg,transparent 0 79px,var(--finish-line) 79px 80px),repeating-linear-gradient(0deg,transparent 0 79px,var(--finish-line) 79px 80px);
}
