 --finish-aperture:7px;--finish-angle:100deg;--finish-alpha:0.04;--finish-pattern:linear-gradient(90deg,var(--finish-line) 1px,transparent 1px),linear-gradient(0deg,var(--finish-line) 1px,transparent 1px);
}
:host([data-owner="atelier"][data-theme="peach"]),.mini-screen[data-theme="peach"],html[data-atelier-world-enabled="true"][data-atelier-world="peach"]{
 --finish-aperture:36px 9px 36px 9px;--finish-angle:140deg;--finish-alpha:0.025;--finish-pattern:radial-gradient(ellipse at 85% 110%,transparent 55%,var(--finish-line) 55.2%,transparent 55.5%,transparent 71%,var(--finish-line) 71.2%,transparent 71.5%);
}
